//! Hand written tokenizer for the Nix language.

use crate::kinds::*;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum IdentType {
    Ident,
    Path,
    Store,
    Uri,
}

fn is_valid_path_char(c: char) -> bool {
    matches!(c, 'a'..='z' | 'A'..='Z' | '0'..='9' | '/' | '_' | '.' | '+' | '-')
}

fn is_valid_uri_char(c: char) -> bool {
    match c {
        '%' | '?' | ':' | '@' | '&' | '=' | '$' | ',' | '!' | '~' | '*' | '\'' => true,
        _ => is_valid_path_char(c),
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Context {
    StringBody { multiline: bool },
    StringEnd,
    Interpol { brackets: u32 },
    InterpolStart,
    Path,
}

pub struct Token {
    pub kind: SyntaxKind,
    pub start: usize,
    pub end: usize,
}

struct Lexer<'a> {
    input: &'a str,
    offset: usize,
    ctx: Vec<Context>,
}

impl<'a> Lexer<'a> {
    fn remaining(&self) -> &'a str {
        &self.input[self.offset..]
    }

    fn peek(&self) -> Option<char> {
        self.remaining().chars().next()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek()?;
        self.offset += c.len_utf8();
        Some(c)
    }

    fn starts_with_bump(&mut self, s: &str) -> bool {
        if self.remaining().starts_with(s) {
            self.offset += s.len();
            true
        } else {
            false
        }
    }

    fn str_since(&self, start: usize) -> &'a str {
        &self.input[start..self.offset]
    }

    fn consume<F: Fn(char) -> bool>(&mut self, f: F) -> usize {
        let mut len = 0;
        while let Some(c) = self.peek() {
            if !f(c) {
                break;
            }
            self.next();
            len += 1;
        }
        len
    }

    fn consume_scientific(&mut self) -> SyntaxKind {
        if self.peek() == Some('e') || self.peek() == Some('E') {
            self.next();
            if self.peek() == Some('-') || self.peek() == Some('+') {
                self.next();
            }
            if self.consume(|c| c.is_ascii_digit()) == 0 {
                return TOKEN_ERROR;
            }
        }
        TOKEN_FLOAT
    }

    fn next_string(&mut self, multiline: bool) -> SyntaxKind {
        loop {
            let start = self.offset;
            match self.next() {
                None => {
                    self.ctx.pop();
                    return TOKEN_ERROR;
                }
                Some('"') if !multiline => {
                    self.offset = start;
                    self.ctx.pop();
                    self.ctx.push(Context::StringEnd);
                    return TOKEN_STRING_CONTENT;
                }
                Some('\\') if !multiline => match self.next() {
                    None => {
                        self.ctx.pop();
                        return TOKEN_ERROR;
                    }
                    Some(_) => (),
                },
                Some('\'') if multiline => match self.peek() {
                    None => {
                        self.ctx.pop();
                        return TOKEN_ERROR;
                    }
                    Some('\'') => {
                        self.next();
                        match self.peek() {
                            Some('\'') | Some('\\') | Some('$') => {
                                self.next();
                            }
                            _ => {
                                self.offset = start;
                                self.ctx.pop();
                                self.ctx.push(Context::StringEnd);
                                return TOKEN_STRING_CONTENT;
                            }
                        }
                    }
                    Some(_) => (),
                },
                Some('$') => match self.peek() {
                    Some('$') => {
                        self.next();
                    }
                    Some('{') => {
                        self.offset = start;
                        self.ctx.push(Context::InterpolStart);
                        return TOKEN_STRING_CONTENT;
                    }
                    _ => (),
                },
                Some(_) => (),
            }
        }
    }

    fn next_token(&mut self) -> Option<SyntaxKind> {
        let start = self.offset;

        loop {
            match self.ctx.last().copied() {
                Some(Context::InterpolStart) => {
                    self.ctx.pop();
                    self.ctx.push(Context::Interpol { brackets: 0 });
                    if self.starts_with_bump("${") {
                        return Some(TOKEN_INTERPOL_START);
                    }
                }
                Some(Context::Path) => {
                    if self.starts_with_bump("${") {
                        self.ctx.push(Context::Interpol { brackets: 0 });
                        return Some(TOKEN_INTERPOL_START);
                    } else if self.peek().map_or(false, is_valid_path_char) {
                        self.consume(is_valid_path_char);
                        return Some(TOKEN_PATH);
                    } else {
                        self.ctx.pop();
                    }
                }
                Some(Context::StringBody { multiline }) => {
                    let token = self.next_string(multiline);
                    // skip empty content
                    if self.offset == start {
                        continue;
                    }
                    return Some(token);
                }
                Some(Context::StringEnd) => {
                    self.ctx.pop();
                    let status = match self.peek() {
                        Some('"') => {
                            self.next();
                            true
                        }
                        Some('\'') => {
                            self.next();
                            match self.peek() {
                                Some('\'') => {
                                    self.next();
                                    true
                                }
                                _ => false,
                            }
                        }
                        _ => false,
                    };
                    return Some(if status { TOKEN_STRING_END } else { TOKEN_ERROR });
                }
                _ => (),
            }
            break;
        }

        if self.consume(char::is_whitespace) > 0 {
            return Some(TOKEN_WHITESPACE);
        }

        if self.peek() == Some('#') {
            self.consume(|c| c != '\n');
            return Some(TOKEN_COMMENT);
        }
        if self.starts_with_bump("/*") {
            loop {
                self.consume(|c| c != '*');
                self.next();
                match self.peek() {
                    None => return Some(TOKEN_ERROR),
                    Some('/') => {
                        self.next();
                        return Some(TOKEN_COMMENT);
                    }
                    _ => (),
                }
            }
        }

        if self.starts_with_bump("...") {
            return Some(TOKEN_ELLIPSIS);
        }

        // Check if it's a path
        let store_path = self.peek() == Some('<');
        let kind = {
            let mut lookahead = self.remaining().chars().skip_while(|&c| match c {
                '<' | '/' => store_path,
                _ => is_valid_path_char(c),
            });

            match (lookahead.next(), lookahead.next()) {
                // a//b parses as Update(a, b)
                (Some('/'), Some('/')) => None,
                (Some('/'), Some('*')) => None,
                (Some('/'), Some(c)) if !c.is_whitespace() => Some(IdentType::Path),
                (Some('>'), _) => Some(IdentType::Store),
                (Some(':'), Some(c)) if is_valid_uri_char(c) && !store_path => Some(IdentType::Uri),
                _ => None,
            }
        };

        let c = self.next()?;

        if c == '~' || kind == Some(IdentType::Path) {
            return Some(if c == '~' && self.next() != Some('/') {
                TOKEN_ERROR
            } else {
                self.consume(is_valid_path_char);
                let since = self.str_since(start);
                if self.remaining().starts_with("${") {
                    self.ctx.push(Context::Path);
                } else if since.ends_with('/') {
                    return Some(TOKEN_ERROR);
                }
                TOKEN_PATH
            });
        }

        Some(match c {
            '=' if self.peek() == Some('=') => {
                self.next();
                TOKEN_EQUAL
            }
            '!' if self.peek() == Some('=') => {
                self.next();
                TOKEN_NOT_EQUAL
            }
            '!' => TOKEN_INVERT,
            '{' => {
                if let Some(Context::Interpol { brackets }) = self.ctx.last_mut() {
                    *brackets += 1;
                }
                TOKEN_L_BRACE
            }
            '}' => {
                if let Some(Context::Interpol { brackets }) = self.ctx.last_mut() {
                    match brackets.checked_sub(1) {
                        Some(new) => *brackets = new,
                        None => {
                            self.ctx.pop();
                            return Some(TOKEN_INTERPOL_END);
                        }
                    }
                }
                TOKEN_R_BRACE
            }
            '[' => TOKEN_L_BRACK,
            ']' => TOKEN_R_BRACK,
            '@' => TOKEN_AT,
            ':' => TOKEN_COLON,
            ',' => TOKEN_COMMA,
            '.' => {
                if self.peek().map_or(false, |x| x.is_ascii_digit()) {
                    self.consume(|c| c.is_ascii_digit());
                    self.consume_scientific()
                } else {
                    TOKEN_DOT
                }
            }
            '=' => TOKEN_ASSIGN,
            '?' => TOKEN_QUESTION,
            ';' => TOKEN_SEMICOLON,
            '(' => TOKEN_L_PAREN,
            ')' => TOKEN_R_PAREN,
            '+' if self.peek() == Some('+') => {
                self.next();
                TOKEN_CONCAT
            }
            '-' if self.peek() == Some('>') => {
                self.next();
                TOKEN_IMPLICATION
            }
            '/' if self.peek() == Some('/') => {
                self.next();
                TOKEN_UPDATE
            }
            '+' => TOKEN_ADD,
            '-' => TOKEN_SUB,
            '*' => TOKEN_MUL,
            '/' => TOKEN_DIV,
            '<' if kind == Some(IdentType::Store) => {
                self.consume(is_valid_path_char);
                if self.next() != Some('>') {
                    return Some(TOKEN_ERROR);
                }
                TOKEN_PATH
            }
            '&' if self.peek() == Some('&') => {
                self.next();
                TOKEN_AND_AND
            }
            '|' if self.peek() == Some('|') => {
                self.next();
                TOKEN_OR_OR
            }
            '<' if self.peek() == Some('=') => {
                self.next();
                TOKEN_LESS_OR_EQ
            }
            '<' => TOKEN_LESS,
            '>' if self.peek() == Some('=') => {
                self.next();
                TOKEN_MORE_OR_EQ
            }
            '>' => TOKEN_MORE,
            '$' if self.peek() == Some('{') => {
                self.next();
                self.ctx.push(Context::Interpol { brackets: 0 });
                TOKEN_INTERPOL_START
            }
            'a'..='z' | 'A'..='Z' | '_' => {
                let kind = match kind {
                    // It's detected as store if it ends with >, but if it
                    // didn't start with <, that's wrong
                    Some(IdentType::Store) | None => IdentType::Ident,
                    Some(kind) => kind,
                };
                self.consume(|c| match c {
                    'a'..='z' | 'A'..='Z' | '0'..='9' | '_' | '-' | '\'' => true,
                    c => kind == IdentType::Uri && is_valid_uri_char(c),
                });
                match kind {
                    IdentType::Ident => match self.str_since(start) {
                        "assert" => TOKEN_ASSERT,
                        "else" => TOKEN_ELSE,
                        "if" => TOKEN_IF,
                        "in" => TOKEN_IN,
                        "inherit" => TOKEN_INHERIT,
                        "let" => TOKEN_LET,
                        "or" => TOKEN_OR,
                        "rec" => TOKEN_REC,
                        "then" => TOKEN_THEN,
                        "with" => TOKEN_WITH,
                        _ => TOKEN_IDENT,
                    },
                    IdentType::Uri => TOKEN_URI,
                    _ => TOKEN_ERROR,
                }
            }
            '"' => {
                self.ctx.push(Context::StringBody { multiline: false });
                TOKEN_STRING_START
            }
            '\'' if self.peek() == Some('\'') => {
                self.next();
                self.ctx.push(Context::StringBody { multiline: true });
                TOKEN_STRING_START
            }
            '0'..='9' => {
                self.consume(|c| c.is_ascii_digit());
                if self.peek() == Some('.') {
                    self.next();
                    self.consume(|c| c.is_ascii_digit());
                    self.consume_scientific()
                } else {
                    TOKEN_INTEGER
                }
            }
            _ => TOKEN_ERROR,
        })
    }
}

pub fn tokenize(input: &str) -> Vec<Token> {
    let mut lexer = Lexer { input, offset: 0, ctx: Vec::new() };
    let mut out = Vec::new();
    loop {
        let start = lexer.offset;
        match lexer.next_token() {
            Some(kind) => {
                out.push(Token { kind, start, end: lexer.offset });
                if lexer.offset == start {
                    // Safety net: should not happen, but avoid infinite loops.
                    if lexer.offset >= input.len() {
                        break;
                    }
                    lexer.offset += input[start..].chars().next().map_or(1, |c| c.len_utf8());
                }
            }
            None => break,
        }
    }
    out
}
EOF
