    pub id: TokenId,
}

#[derive(Clone, Copy)]
pub enum NodeOrToken<'a> {
    Node(Node<'a>),
    Token(Token<'a>),
}

impl<'a> NodeOrToken<'a> {
    pub fn kind(&self) -> SyntaxKind {
        match self {
            NodeOrToken::Node(n) => n.kind(),
            NodeOrToken::Token(t) => t.kind(),
        }
    }
    pub fn range(&self) -> TextRange {
        match self {
            NodeOrToken::Node(n) => n.range(),
            NodeOrToken::Token(t) => t.range(),
        }
    }
    pub fn text(&self) -> &'a str {
        match self {
            NodeOrToken::Node(n) => n.text(),
            NodeOrToken::Token(t) => t.text(),
        }
    }
    pub fn as_node(&self) -> Option<Node<'a>> {
        match self {
            NodeOrToken::Node(n) => Some(*n),
            _ => None,
        }
    }
    pub fn as_token(&self) -> Option<Token<'a>> {
        match self {
            NodeOrToken::Token(t) => Some(*t),
            _ => None,
        }
    }
    pub fn parent(&self) -> Option<Node<'a>> {
        match self {
            NodeOrToken::Node(n) => n.parent(),
            NodeOrToken::Token(t) => t.parent(),
        }
    }
}

impl<'a> PartialEq for Node<'a> {
    fn eq(&self, other: &Self) -> bool {
        self.id == other.id
    }
}

impl<'a> Node<'a> {
    fn data(&self) -> &'a NodeData {
        &self.tree.nodes[self.id.0]
    }
    pub fn kind(&self) -> SyntaxKind {
        self.data().kind
    }
    pub fn range(&self) -> TextRange {
        TextRange::new(self.data().start, self.data().end)
    }
    pub fn text(&self) -> &'a str {
        &self.tree.text[self.data().start..self.data().end]
    }
    pub fn parent(&self) -> Option<Node<'a>> {
        self.data().parent.map(|id| Node { tree: self.tree, id })
    }
    pub fn children_with_tokens(&self) -> impl Iterator<Item = NodeOrToken<'a>> + 'a {
        let tree = self.tree;
        self.data().children.iter().map(move |e| match e {
            Element::Node(id) => NodeOrToken::Node(Node { tree, id: *id }),
            Element::Token(id) => NodeOrToken::Token(Token { tree, id: *id }),
        })
    }
    pub fn children(&self) -> impl Iterator<Item = Node<'a>> + 'a {
        self.children_with_tokens().filter_map(|e| e.as_node())
    }
    pub fn tokens(&self) -> impl Iterator<Item = Token<'a>> + 'a {
        self.children_with_tokens().filter_map(|e| e.as_token())
    }
    pub fn first_child(&self) -> Option<Node<'a>> {
        self.children().next()
    }
    pub fn first_token_of_kind(&self, kind: SyntaxKind) -> Option<Token<'a>> {
        self.tokens().find(|t| t.kind() == kind)
    }
    pub fn first_child_of_kind(&self, kind: SyntaxKind) -> Option<Node<'a>> {
        self.children().find(|t| t.kind() == kind)
    }
    pub fn index_in_parent(&self) -> Option<usize> {
        let parent = self.parent()?;
        parent.children_with_tokens().position(|e| match e {
            NodeOrToken::Node(n) => n.id == self.id,
            _ => false,
        })
    }
    pub fn next_sibling(&self) -> Option<Node<'a>> {
        let parent = self.parent()?;
        let mut found = false;
        for c in parent.children() {
            if found {
                return Some(c);
            }
            if c.id == self.id {
                found = true;
            }
        }
        None
    }
    pub fn prev_sibling(&self) -> Option<Node<'a>> {
        let parent = self.parent()?;
        let mut prev = None;
        for c in parent.children() {
            if c.id == self.id {
                return prev;
            }
            prev = Some(c);
        }
        None
    }
    pub fn next_sibling_or_token(&self) -> Option<NodeOrToken<'a>> {
        let parent = self.parent()?;
        let mut found = false;
        for c in parent.children_with_tokens() {
            if found {
                return Some(c);
            }
            if let NodeOrToken::Node(n) = c {
                if n.id == self.id {
                    found = true;
                }
            }
        }
        None
    }
    pub fn prev_sibling_or_token(&self) -> Option<NodeOrToken<'a>> {
        let parent = self.parent()?;
        let mut prev = None;
        for c in parent.children_with_tokens() {
            if let NodeOrToken::Node(n) = c {
                if n.id == self.id {
                    return prev;
                }
            }
            prev = Some(c);
        }
        None
    }
    /// First token in the subtree (including trivia).
    pub fn first_token(&self) -> Option<Token<'a>> {
        for c in self.children_with_tokens() {
            match c {
                NodeOrToken::Token(t) => return Some(t),
                NodeOrToken::Node(n) => {
                    if let Some(t) = n.first_token() {
                        return Some(t);
                    }
                }
            }
        }
        None
    }
    pub fn last_token(&self) -> Option<Token<'a>> {
        let children: Vec<_> = self.children_with_tokens().collect();
        for c in children.into_iter().rev() {
            match c {
                NodeOrToken::Token(t) => return Some(t),
                NodeOrToken::Node(n) => {
                    if let Some(t) = n.last_token() {
                        return Some(t);
                    }
                }
            }
        }
        None
    }
    /// Pre-order traversal of all descendant nodes (including self).
    pub fn descendants(&self) -> Vec<Node<'a>> {
        let mut out = Vec::new();
        let mut stack = vec![*self];
        while let Some(n) = stack.pop() {
            out.push(n);
            let children: Vec<_> = n.children().collect();
            for c in children.into_iter().rev() {
                stack.push(c);
            }
        }
        out
    }
    pub fn ancestors(&self) -> Vec<Node<'a>> {
        let mut out = Vec::new();
        let mut cur = Some(*self);
        while let Some(n) = cur {
            out.push(n);
            cur = n.parent();
        }
        out
    }
}

impl<'a> Token<'a> {
    fn data(&self) -> &'a TokenData {
        &self.tree.tokens[self.id.0]
    }
    pub fn kind(&self) -> SyntaxKind {
        self.data().kind
    }
    pub fn range(&self) -> TextRange {
        TextRange::new(self.data().start, self.data().end)
    }
    pub fn text(&self) -> &'a str {
        &self.tree.text[self.data().start..self.data().end]
    }
    pub fn parent(&self) -> Option<Node<'a>> {
        self.data().parent.map(|id| Node { tree: self.tree, id })
    }
}

impl Tree {
    pub fn root(&self) -> Node<'_> {
        Node { tree: self, id: self.root }
    }
    pub fn node(&self, id: NodeId) -> Node<'_> {
        Node { tree: self, id }
    }
}

/// Builder that mimics rowan's GreenNodeBuilder, including checkpoints.
pub struct TreeBuilder {
    text: String,
    nodes: Vec<NodeData>,
    tokens: Vec<TokenData>,
    // stack of (node id, children collected so far)
    stack: Vec<(SyntaxKind, Vec<Element>)>,
    pos: usize,
}

#[derive(Clone, Copy, Debug)]
pub struct Checkpoint {
    depth: usize,
    child_index: usize,
}

impl TreeBuilder {
    pub fn new(text: &str) -> Self {
        TreeBuilder {
            text: text.to_string(),
            nodes: Vec::new(),
            tokens: Vec::new(),
            stack: Vec::new(),
            pos: 0,
        }
    }

    pub fn start_node(&mut self, kind: SyntaxKind) {
        self.stack.push((kind, Vec::new()));
    }

    pub fn checkpoint(&self) -> Checkpoint {
        let (depth, child_index) = match self.stack.last() {
            Some((_, children)) => (self.stack.len(), children.len()),
            None => (0, 0),
        };
        Checkpoint { depth, child_index }
    }

    pub fn start_node_at(&mut self, checkpoint: Checkpoint, kind: SyntaxKind) {
        // The checkpoint must refer to the current top of stack.
        assert_eq!(checkpoint.depth, self.stack.len(), "checkpoint no longer valid");
        let (_, children) = self.stack.last_mut().unwrap();
        let moved: Vec<Element> = children.drain(checkpoint.child_index..).collect();
        self.stack.push((kind, moved));
    }

    pub fn token(&mut self, kind: SyntaxKind, len: usize) {
        let id = TokenId(self.tokens.len());
        self.tokens.push(TokenData { kind, start: self.pos, end: self.pos + len, parent: None });
        self.pos += len;
        if let Some((_, children)) = self.stack.last_mut() {
            children.push(Element::Token(id));
        }
    }

    pub fn finish_node(&mut self) {
        let (kind, children) = self.stack.pop().expect("unbalanced finish_node");
        let id = NodeId(self.nodes.len());
        // compute range
        let mut start = None;
        let mut end = None;
        for c in &children {
            let (s, e) = match c {
                Element::Node(n) => (self.nodes[n.0].start, self.nodes[n.0].end),
                Element::Token(t) => (self.tokens[t.0].start, self.tokens[t.0].end),
            };
            if start.is_none() {
                start = Some(s);
            }
            end = Some(e);
        }
        let (start, end) = match (start, end) {
            (Some(s), Some(e)) => (s, e),
            _ => (self.pos, self.pos),
        };
        for c in &children {
            match c {
                Element::Node(n) => self.nodes[n.0].parent = Some(id),
                Element::Token(t) => self.tokens[t.0].parent = Some(id),
            }
        }
        self.nodes.push(NodeData { kind, start, end, parent: None, children });
        if let Some((_, parent_children)) = self.stack.last_mut() {
            parent_children.push(Element::Node(id));
        }
    }

    pub fn finish(self) -> Tree {
        assert!(self.stack.is_empty());
        let root = NodeId(self.nodes.len() - 1);
        Tree { text: self.text, nodes: self.nodes, tokens: self.tokens, root }
    }
}
