//! Parser producing a lossless syntax tree, modelled closely after the
//! behaviour of the reference Nix parser used by the original tool.

use crate::kinds::*;
use crate::lexer::{tokenize, Token};
use crate::syntax::{Checkpoint, TextRange, Tree, TreeBuilder};
use std::collections::VecDeque;
use std::fmt;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ParseError {
    /// Unexpected token(s) at the end of the file.
    UnexpectedExtra(TextRange),
    UnexpectedWanted(SyntaxKind, TextRange, Vec<SyntaxKind>),
    UnexpectedDoubleBind(TextRange),
    UnexpectedEOF,
    UnexpectedEOFWanted(Vec<SyntaxKind>),
    DuplicatedArgs(TextRange, String),
    RecursionLimitExceeded,
}

fn fmt_kinds(kinds: &[SyntaxKind]) -> String {
    let parts: Vec<String> = kinds.iter().map(|k| format!("{:?}", k)).collect();
    format!("[{}]", parts.join(", "))
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            ParseError::UnexpectedExtra(range) => write!(f, "unexpected token at {}", range),
            ParseError::UnexpectedWanted(got, range, kinds) => {
                write!(f, "unexpected {:?} at {}, wanted any of {}", got, range, fmt_kinds(kinds))
            }
            ParseError::UnexpectedDoubleBind(range) => {
                write!(f, "unexpected double bind at {}", range)
            }
            ParseError::UnexpectedEOF => write!(f, "unexpected end of file"),
            ParseError::UnexpectedEOFWanted(kinds) => {
                write!(f, "unexpected end of file, wanted any of {}", fmt_kinds(kinds))
            }
            ParseError::DuplicatedArgs(range, ident) => {
                write!(f, "argument `{}` is duplicated in {}", ident, range)
            }
            ParseError::RecursionLimitExceeded => write!(f, "recursion limit exceeded"),
        }
    }
}

impl ParseError {
    pub fn range(&self) -> Option<TextRange> {
        match self {
            ParseError::UnexpectedExtra(r)
            | ParseError::UnexpectedWanted(_, r, _)
            | ParseError::UnexpectedDoubleBind(r)
            | ParseError::DuplicatedArgs(r, _) => Some(*r),
            _ => None,
        }
    }
}

pub struct Parse {
    pub tree: Tree,
    pub errors: Vec<ParseError>,
}

struct Parser<'a> {
    text: &'a str,
    builder: TreeBuilder,
    errors: Vec<ParseError>,
    trivia_buffer: Vec<Token>,
    buffer: VecDeque<Token>,
    tokens: std::vec::IntoIter<Token>,
    consumed: usize,
    depth: u32,
}

const VALUE_START: &[SyntaxKind] = &[
    TOKEN_L_PAREN,
    TOKEN_REC,
    TOKEN_L_BRACE,
    TOKEN_L_BRACK,
    TOKEN_STRING_START,
    TOKEN_IDENT,
];

impl<'a> Parser<'a> {
    fn new(text: &'a str) -> Self {
        Parser {
            text,
            builder: TreeBuilder::new(text),
            errors: Vec::new(),
            trivia_buffer: Vec::new(),
            buffer: VecDeque::new(),
            tokens: tokenize(text).into_iter(),
            consumed: 0,
            depth: 0,
        }
    }

    fn text_position(&self) -> usize {
        self.consumed
    }

    fn peek_raw(&mut self) -> Option<&Token> {
        if self.buffer.is_empty() {
            if let Some(token) = self.tokens.next() {
                self.buffer.push_back(token);
            }
        }
        self.buffer.front()
    }

    fn peek_raw_nth(&mut self, n: usize) -> Option<&Token> {
        while self.buffer.len() <= n {
            match self.tokens.next() {
                Some(t) => self.buffer.push_back(t),
                None => break,
            }
        }
        self.buffer.get(n)
    }

    /// Peek the n-th upcoming non-trivia token (0 = next non-trivia token).
    fn peek_nth(&mut self, n: usize) -> Option<SyntaxKind> {
        let mut found = 0;
        let mut i = 0;
        loop {
            let kind = self.peek_raw_nth(i)?.kind;
            if !kind.is_trivia() {
                if found == n {
                    return Some(kind);
                }
                found += 1;
            }
            i += 1;
        }
    }

    fn eat_trivia(&mut self) {
        self.peek();
        self.drain_trivia_buffer();
    }

    fn start_node(&mut self, kind: SyntaxKind) {
        self.eat_trivia();
        self.builder.start_node(kind);
    }

    fn checkpoint(&mut self) -> Checkpoint {
        self.eat_trivia();
        self.builder.checkpoint()
    }

    fn start_node_at(&mut self, checkpoint: Checkpoint, kind: SyntaxKind) {
        self.builder.start_node_at(checkpoint, kind);
    }

    fn finish_node(&mut self) {
        self.builder.finish_node();
    }

    fn start_error_node(&mut self) -> usize {
        self.start_node(NODE_ERROR);
        self.text_position()
    }

    fn finish_error_node(&mut self) -> usize {
        self.finish_node();
        self.text_position()
    }

    fn bump(&mut self) {
        let next = self.buffer.pop_front().or_else(|| self.tokens.next());
        match next {
            Some(token) => {
                if token.kind.is_trivia() {
                    self.trivia_buffer.push(token);
                } else {
                    self.drain_trivia_buffer();
                    self.manual_bump(token);
                }
            }
            None => self.errors.push(ParseError::UnexpectedEOF),
        }
    }

    fn drain_trivia_buffer(&mut self) {
        let buf: Vec<Token> = self.trivia_buffer.drain(..).collect();
        for t in buf {
            self.manual_bump(t);
        }
    }

    fn manual_bump(&mut self, token: Token) {
        let len = token.end - token.start;
        self.consumed += len;
        self.builder.token(token.kind, len);
    }

    fn peek_data(&mut self) -> Option<&Token> {
        while self.peek_raw().map(|t| t.kind.is_trivia()).unwrap_or(false) {
            self.bump();
        }
        self.peek_raw()
    }

    fn peek(&mut self) -> Option<SyntaxKind> {
        self.peek_data().map(|t| t.kind)
    }

    fn expect_peek_any(&mut self, allowed: &[SyntaxKind]) -> Option<SyntaxKind> {
        let next = match self.peek() {
            None => None,
            Some(kind) if allowed.contains(&kind) => Some(kind),
            Some(kind) => {
                let start = self.start_error_node();
                loop {
                    self.bump();
                    if self.peek().map(|kind| allowed.contains(&kind)).unwrap_or(true) {
                        break;
                    }
                }
                let end = self.finish_error_node();
                self.errors.push(ParseError::UnexpectedWanted(
                    kind,
                    TextRange::new(start, end),
                    allowed.to_vec(),
                ));
                self.peek()
            }
        };
        if next.is_none() {
            self.errors.push(ParseError::UnexpectedEOFWanted(allowed.to_vec()));
        }
        next
    }

    fn expect(&mut self, expected: SyntaxKind) {
        if self.expect_peek_any(&[expected]).is_some() {
            self.bump();
        }
    }

    fn expect_ident(&mut self) {
        if self.expect_peek_any(&[TOKEN_IDENT, TOKEN_OR]).is_some() {
            self.start_node(NODE_IDENT);
            self.bump();
            self.finish_node();
        }
    }

    fn parse_dynamic(&mut self) {
        self.start_node(NODE_DYNAMIC);
        self.bump();
        while self.peek().map(|t| t != TOKEN_INTERPOL_END).unwrap_or(false) {
            self.parse_expr();
        }
        self.bump();
        self.finish_node();
    }

    fn parse_string(&mut self) {
        self.start_node(NODE_STRING);
        self.expect(TOKEN_STRING_START);

        loop {
            match self.expect_peek_any(&[
                TOKEN_STRING_END,
                TOKEN_STRING_CONTENT,
                TOKEN_INTERPOL_START,
            ]) {
                Some(TOKEN_STRING_CONTENT) => self.bump(),
                Some(TOKEN_INTERPOL_START) => {
                    self.start_node(NODE_INTERPOL);
                    self.bump();
                    self.parse_expr();
                    self.expect(TOKEN_INTERPOL_END);
                    self.finish_node();
                }
                // handled by expect_peek_any
                _ => break,
            }
        }
        self.expect(TOKEN_STRING_END);
        self.finish_node();
    }

    fn next_attr(&mut self) {
        match self.peek() {
            Some(TOKEN_INTERPOL_START) => self.parse_dynamic(),
            Some(TOKEN_STRING_START) => self.parse_string(),
            _ => self.expect_ident(),
        }
    }

    fn parse_attrpath(&mut self) {
        self.start_node(NODE_ATTRPATH);
        loop {
            self.next_attr();
            if self.peek() == Some(TOKEN_DOT) {
                self.bump();
            } else {
                break;
            }
        }
        self.finish_node();
    }

    fn parse_pattern(&mut self, bound: bool) {
        if self.peek().map(|t| t == TOKEN_R_BRACE).unwrap_or(true) {
            self.bump();
        } else {
            loop {
                match self.expect_peek_any(&[TOKEN_R_BRACE, TOKEN_ELLIPSIS, TOKEN_IDENT]) {
                    Some(TOKEN_R_BRACE) => {
                        self.bump();
                        break;
                    }
                    Some(TOKEN_ELLIPSIS) => {
                        self.bump();
                        self.expect(TOKEN_R_BRACE);
                        break;
                    }
                    Some(TOKEN_IDENT) => {
                        self.start_node(NODE_PAT_ENTRY);
                        self.start_node(NODE_IDENT);
                        self.bump();
                        self.finish_node();
                        if let Some(TOKEN_QUESTION) = self.peek() {
                            self.bump();
                            self.parse_expr();
                        }
                        self.finish_node();

                        match self.peek() {
                            Some(TOKEN_COMMA) => self.bump(),
                            _ => {
                                self.expect(TOKEN_R_BRACE);
                                break;
                            }
                        }
                    }
                    _ => break,
                }
            }
        }

        if self.peek() == Some(TOKEN_AT) {
            let kind = if bound { NODE_ERROR } else { NODE_PAT_BIND };
            self.start_node(kind);
            let start = self.text_position();
            self.bump();
            self.expect_ident();
            self.finish_node();
            let end = self.text_position();
            if bound {
                self.errors.push(ParseError::UnexpectedDoubleBind(TextRange::new(start, end)));
            }
        }
    }

    fn parse_set(&mut self, until: SyntaxKind) {
        loop {
            match self.peek() {
                None => break,
                token if token == Some(until) => break,
                Some(TOKEN_INHERIT) => {
                    self.start_node(NODE_INHERIT);
                    self.bump();

                    if self.peek() == Some(TOKEN_L_PAREN) {
                        self.start_node(NODE_INHERIT_FROM);
                        self.bump();
                        self.parse_expr();
                        self.expect(TOKEN_R_PAREN);
                        self.finish_node();
                    }

                    loop {
                        match self.peek() {
                            Some(TOKEN_SEMICOLON) | None => break,
                            Some(TOKEN_INTERPOL_START) => self.parse_dynamic(),
                            Some(TOKEN_STRING_START) => self.parse_string(),
                            _ => self.expect_ident(),
                        }
                        if self.peek() == Some(until) && until != TOKEN_SEMICOLON {
                            // avoid infinite loops on a stray closing token
                            if !matches!(self.peek(), Some(TOKEN_IDENT) | Some(TOKEN_OR)) {
                                break;
                            }
                        }
                    }

                    self.expect(TOKEN_SEMICOLON);
                    self.finish_node();
                }
                Some(_) => {
                    self.start_node(NODE_ATTRPATH_VALUE);
                    self.parse_attrpath();
                    self.expect(TOKEN_ASSIGN);
                    self.parse_expr();
                    self.expect(TOKEN_SEMICOLON);
                    self.finish_node();
                }
            }
        }
        self.bump(); // the final close, like '}'
    }

    fn parse_val(&mut self) -> Checkpoint {
        let checkpoint = self.checkpoint();
        match self.peek() {
            Some(TOKEN_L_PAREN) => {
                self.start_node(NODE_PAREN);
                self.bump();
                self.parse_expr();
                self.bump();
                self.finish_node();
            }
            Some(TOKEN_REC) => {
                self.start_node(NODE_ATTR_SET);
                self.bump();
                self.expect(TOKEN_L_BRACE);
                self.parse_set(TOKEN_R_BRACE);
                self.finish_node();
            }
            Some(TOKEN_L_BRACE) => {
                // Do a lookahead to see if this is a lambda or attrset
                let kind = match (self.peek_nth(1), self.peek_nth(2)) {
                    (Some(TOKEN_IDENT), Some(TOKEN_COMMA))
                    | (Some(TOKEN_IDENT), Some(TOKEN_QUESTION))
                    | (Some(TOKEN_IDENT), Some(TOKEN_R_BRACE))
                    | (Some(TOKEN_ELLIPSIS), _)
                    | (Some(TOKEN_R_BRACE), Some(TOKEN_COLON))
                    | (Some(TOKEN_R_BRACE), Some(TOKEN_AT)) => NODE_PATTERN,
                    _ => NODE_ATTR_SET,
                };
                if kind == NODE_PATTERN {
                    self.start_node(NODE_LAMBDA);
                    self.start_node(NODE_PATTERN);
                    self.bump();
                    self.parse_pattern(false);
                    self.finish_node();
                    self.expect(TOKEN_COLON);
                    self.parse_expr();
                    self.finish_node();
                } else {
                    self.start_node(NODE_ATTR_SET);
                    self.bump();
                    self.parse_set(TOKEN_R_BRACE);
                    self.finish_node();
                }
            }
            Some(TOKEN_L_BRACK) => {
                self.start_node(NODE_LIST);
                self.bump();
                while self.peek().map(|t| t != TOKEN_R_BRACK).unwrap_or(false) {
                    self.parse_val();
                }
                self.bump();
                self.finish_node();
            }
            Some(TOKEN_STRING_START) => self.parse_string(),
            Some(TOKEN_PATH) => {
                self.start_node(NODE_PATH);
                self.bump();
                loop {
                    match self.peek_raw().map(|t| t.kind) {
                        Some(TOKEN_PATH) => self.bump(),
                        Some(TOKEN_INTERPOL_START) => {
                            self.start_node(NODE_INTERPOL);
                            self.bump();
                            self.parse_expr();
                            self.expect(TOKEN_INTERPOL_END);
                            self.finish_node();
                        }
                        _ => break,
                    }
                }
                self.finish_node();
            }
            Some(t) if t.is_literal() => {
                self.start_node(NODE_LITERAL);
                self.bump();
                self.finish_node();
            }
            Some(TOKEN_IDENT) => {
                self.start_node(NODE_IDENT);
                self.bump();
                self.finish_node();

                match self.peek() {
                    Some(TOKEN_COLON) => {
                        self.start_node_at(checkpoint, NODE_LAMBDA);
                        self.start_node_at(checkpoint, NODE_IDENT_PARAM);
                        self.finish_node();
                        self.bump();
                        self.parse_expr();
                        self.finish_node();
                    }
                    Some(TOKEN_AT) => {
                        self.start_node_at(checkpoint, NODE_LAMBDA);
                        self.start_node_at(checkpoint, NODE_PATTERN);
                        self.start_node_at(checkpoint, NODE_PAT_BIND);
                        self.bump();
                        self.finish_node(); // PatBind
                        self.expect(TOKEN_L_BRACE);
                        self.parse_pattern(true);
                        self.finish_node(); // Pattern
                        self.expect(TOKEN_COLON);
                        self.parse_expr();
                        self.finish_node(); // Lambda
                    }
                    _ => (),
                }
            }
            Some(kind) => {
                let start = self.start_error_node();
                self.bump();
                let end = self.finish_error_node();
                self.errors.push(ParseError::UnexpectedWanted(
                    kind,
                    TextRange::new(start, end),
                    VALUE_START.to_vec(),
                ));
            }
            None => {
                self.errors.push(ParseError::UnexpectedEOF);
                return checkpoint;
            }
        }

        while self.peek() == Some(TOKEN_DOT) {
            self.start_node_at(checkpoint, NODE_SELECT);
            self.bump();
            self.parse_attrpath();
            if self.peek() == Some(TOKEN_OR) {
                self.bump();
                self.parse_val();
            }
            self.finish_node();
        }

        // `or` used as a plain identifier in argument position
        if self.peek() == Some(TOKEN_OR) {
            self.start_node_at(checkpoint, NODE_APPLY);
            self.start_node(NODE_IDENT);
            self.bump();
            self.finish_node();
            self.finish_node();
        }

        checkpoint
    }

    fn parse_fn(&mut self) -> Checkpoint {
        let checkpoint = self.parse_val();

        while self.peek().map(|t| t.is_fn_arg()).unwrap_or(false) {
            self.start_node_at(checkpoint, NODE_APPLY);
            self.parse_val();
            self.finish_node();
        }
        checkpoint
    }

    fn parse_negate(&mut self) -> Checkpoint {
        if self.peek() == Some(TOKEN_SUB) {
            let checkpoint = self.checkpoint();
            self.start_node(NODE_UNARY_OP);
            self.bump();
            self.parse_negate();
            self.finish_node();
            checkpoint
        } else {
            self.parse_fn()
        }
    }

    fn handle_operation(
        &mut self,
        once: bool,
        next: fn(&mut Self) -> Checkpoint,
        ops: &[SyntaxKind],
    ) -> Checkpoint {
        let checkpoint = next(self);
        while self.peek().map(|t| ops.contains(&t)).unwrap_or(false) {
            self.start_node_at(checkpoint, NODE_BIN_OP);
            self.bump();
            next(self);
            self.finish_node();
            if once {
                break;
            }
        }
        checkpoint
    }

    fn parse_hasattr(&mut self) -> Checkpoint {
        let checkpoint = self.parse_negate();
        while self.peek() == Some(TOKEN_QUESTION) {
            self.start_node_at(checkpoint, NODE_HAS_ATTR);
            self.bump();
            self.parse_attrpath();
            self.finish_node();
        }
        checkpoint
    }

    fn parse_concat(&mut self) -> Checkpoint {
        self.handle_operation(false, Self::parse_hasattr, &[TOKEN_CONCAT])
    }

    fn parse_mul(&mut self) -> Checkpoint {
        self.handle_operation(false, Self::parse_concat, &[TOKEN_MUL, TOKEN_DIV])
    }

    fn parse_add(&mut self) -> Checkpoint {
        self.handle_operation(false, Self::parse_mul, &[TOKEN_ADD, TOKEN_SUB])
    }

    fn parse_invert(&mut self) -> Checkpoint {
        if self.peek() == Some(TOKEN_INVERT) {
            let checkpoint = self.checkpoint();
            self.start_node(NODE_UNARY_OP);
            self.bump();
            self.parse_invert();
            self.finish_node();
            checkpoint
        } else {
            self.parse_add()
        }
    }

    fn parse_merge(&mut self) -> Checkpoint {
        self.handle_operation(false, Self::parse_invert, &[TOKEN_UPDATE])
    }

    fn parse_compare(&mut self) -> Checkpoint {
        self.handle_operation(
            true,
            Self::parse_merge,
            &[TOKEN_LESS, TOKEN_LESS_OR_EQ, TOKEN_MORE, TOKEN_MORE_OR_EQ],
        )
    }

    fn parse_equal(&mut self) -> Checkpoint {
        self.handle_operation(true, Self::parse_compare, &[TOKEN_EQUAL, TOKEN_NOT_EQUAL])
    }

    fn parse_and(&mut self) -> Checkpoint {
        self.handle_operation(false, Self::parse_equal, &[TOKEN_AND_AND])
    }

    fn parse_or(&mut self) -> Checkpoint {
        self.handle_operation(false, Self::parse_and, &[TOKEN_OR_OR])
    }

    fn parse_implication(&mut self) -> Checkpoint {
        self.handle_operation(false, Self::parse_or, &[TOKEN_IMPLICATION])
    }

    fn parse_math(&mut self) -> Checkpoint {
        self.parse_implication()
    }

    fn parse_expr(&mut self) -> Checkpoint {
        if self.depth >= 512 {
            let checkpoint = self.checkpoint();
            self.errors.push(ParseError::RecursionLimitExceeded);
            // consume the rest to avoid infinite loops
            return checkpoint;
        }
        self.depth += 1;
        let out = match self.peek() {
            Some(TOKEN_LET) => {
                let checkpoint = self.checkpoint();
                self.bump();
                if self.peek() == Some(TOKEN_L_BRACE) {
                    self.start_node_at(checkpoint, NODE_LEGACY_LET);
                    self.bump();
                    self.parse_set(TOKEN_R_BRACE);
                    self.finish_node();
                } else {
                    self.start_node_at(checkpoint, NODE_LET_IN);
                    self.parse_set(TOKEN_IN);
                    self.parse_expr();
                    self.finish_node();
                }
                checkpoint
            }
            Some(TOKEN_WITH) => {
                let checkpoint = self.checkpoint();
                self.start_node(NODE_WITH);
                self.bump();
                self.parse_expr();
                self.expect(TOKEN_SEMICOLON);
                self.parse_expr();
                self.finish_node();
                checkpoint
            }
            Some(TOKEN_IF) => {
                let checkpoint = self.checkpoint();
                self.start_node(NODE_IF_ELSE);
                self.bump();
                self.parse_expr();
                self.expect(TOKEN_THEN);
                self.parse_expr();
                self.expect(TOKEN_ELSE);
                self.parse_expr();
                self.finish_node();
                checkpoint
            }
            Some(TOKEN_ASSERT) => {
                let checkpoint = self.checkpoint();
                self.start_node(NODE_ASSERT);
                self.bump();
                self.parse_expr();
                self.expect(TOKEN_SEMICOLON);
                self.parse_expr();
                self.finish_node();
                checkpoint
            }
            _ => self.parse_math(),
        };
        self.depth -= 1;
        out
    }
}

pub fn parse(text: &str) -> Parse {
    let mut parser = Parser::new(text);
    parser.builder.start_node(NODE_ROOT);
    parser.parse_expr();
    parser.eat_trivia();
    if parser.peek().is_some() {
        let start = parser.start_error_node();
        while parser.peek().is_some() {
            parser.bump();
        }
        let end = parser.finish_error_node();
        parser.errors.push(ParseError::UnexpectedExtra(TextRange::new(start, end)));
        parser.eat_trivia();
    }
    parser.builder.finish_node();
    let _ = parser.text;
    Parse { tree: parser.builder.finish(), errors: parser.errors }
}
