            | NODE_IDENT
            | NODE_WITH
            | NODE_HAS_ATTR
    )
}

pub fn exprs<'a>(node: Node<'a>) -> impl Iterator<Item = Node<'a>> + 'a {
    node.children().filter(|c| is_expr_kind(c.kind()))
