    exprs(node).next()
}

pub fn last_expr(node: Node<'_>) -> Option<Node<'_>> {
    exprs(node).last()
}

pub fn token(node: Node<'_>, kind: SyntaxKind) -> Option<Token<'_>> {
    node.first_token_of_kind(kind)
}

pub fn has_token(node: Node<'_>, kind: SyntaxKind) -> bool {
    token(node, kind).is_some()
}

