pub fn attrs<'a>(attrpath: Node<'a>) -> impl Iterator<Item = Node<'a>> + 'a {
    attrpath
        .children()
        .filter(|c| matches!(c.kind(), NODE_IDENT | NODE_STRING | NODE_DYNAMIC))
}

/// Ident text if the node is an ident.
pub fn ident_text(node: Node<'_>) -> Option<&str> {
    if node.kind() == NODE_IDENT {
        node.tokens()
            .find(|t| matches!(t.kind(), TOKEN_IDENT | TOKEN_OR))
            .map(|t| t.text())
    } else {
        None
    }
}

