pub fn select_expr(node: Node<'_>) -> Option<Node<'_>> {
    first_expr(node)
}
pub fn select_attrpath(node: Node<'_>) -> Option<Node<'_>> {
    node.first_child_of_kind(NODE_ATTRPATH)
}
pub fn select_has_default(node: Node<'_>) -> bool {
    has_token(node, TOKEN_OR)
}

// Lambda
pub fn lambda_param(node: Node<'_>) -> Option<Node<'_>> {
    node.children()
        .find(|c| matches!(c.kind(), NODE_IDENT_PARAM | NODE_PATTERN))
}
pub fn lambda_body(node: Node<'_>) -> Option<Node<'_>> {
    first_expr(node)
}

