    node.children()
        .filter(|c| matches!(c.kind(), NODE_IDENT | NODE_STRING | NODE_DYNAMIC))
}

/// Trim whitespace around a node's text.
pub fn trimmed_text(node: Node<'_>) -> &str {
    node.text().trim()
}

/// The text of all children (tokens and nodes) strictly between two tokens
/// `from` (exclusive) and `to` (exclusive) within `node`.
pub fn text_between(node: Node<'_>, from: Token<'_>, to: Token<'_>) -> String {
    let mut out = String::new();
    let mut inside = false;
    for c in node.children_with_tokens() {
        if let NodeOrToken::Token(t) = c {
            if t.id == from.id {
                inside = true;
                continue;
            }
            if t.id == to.id {
                break;
            }
        }
        if inside {
            out.push_str(c.text());
        }
    }
    out
}

/// The text of all children after token `from` (exclusive).
pub fn text_after(node: Node<'_>, from: Token<'_>) -> String {
    let mut out = String::new();
    let mut inside = false;
    for c in node.children_with_tokens() {
        if let NodeOrToken::Token(t) = c {
            if t.id == from.id {
                inside = true;
                continue;
            }
        }
        if inside {
            out.push_str(c.text());
        }
    }
    out
}
