// W02
// ---------------------------------------------------------------------------

fn empty_let_in(node: Node<'_>) -> Vec<Report> {
    if entries(node).next().is_some() {
        return vec![];
    }
    let body = match last_expr(node) {
        Some(b) => b,
        None => return vec![],
    };
    let at = node.range();
    let message = "This let-in expression has no entries";
    let has_comment = node.tokens().any(|t| t.kind() == TOKEN_COMMENT);
    let report = Report::new(2, "Useless let-in expression");
    if has_comment {
        vec![report.diagnostic(at, message)]
    } else {
        vec![report.suggest(at, message, at, body.text())]
    }
}

// ---------------------------------------------------------------------------
// W03
// ---------------------------------------------------------------------------

fn single_ident_key(apv: Node<'_>) -> Option<Node<'_>> {
    let attrpath = apv_attrpath(apv)?;
    let mut it = attrs(attrpath);
    let first = it.next()?;
    if it.next().is_some() {
        return None;
    }
    if first.kind() == NODE_IDENT {
        Some(first)
    } else {
        None
    }
}

fn manual_inherit(node: Node<'_>) -> Vec<Report> {
    let key = match single_ident_key(node) {
        Some(k) => k,
        None => return vec![],
    };
    let value = match apv_value(node) {
        Some(v) => v,
        None => return vec![],
    };
    if value.kind() != NODE_IDENT {
        return vec![];
    }
    if ident_text(key) != ident_text(value) {
        return vec![];
    }
    let at = node.range();
    let replacement = format!("inherit {};", key.text());
    let message = "This assignment is better written with `inherit`";
    vec![Report::new(3, "Assignment instead of inherit").suggest(at, message, at, replacement)]
}

// ---------------------------------------------------------------------------
// W04
// ---------------------------------------------------------------------------

fn manual_inherit_from(node: Node<'_>) -> Vec<Report> {
    let key = match single_ident_key(node) {
        Some(k) => k,
        None => return vec![],
    };
    let value = match apv_value(node) {
        Some(v) => v,
        None => return vec![],
    };
    if value.kind() != NODE_SELECT {
        return vec![];
    }
    let set = match select_expr(value) {
        Some(s) => s,
        None => return vec![],
    };
    let attrpath = match select_attrpath(value) {
        Some(a) => a,
        None => return vec![],
    };
    let mut it = attrs(attrpath);
    let index = match it.next() {
        Some(i) => i,
        None => return vec![],
    };
    if it.next().is_some() {
        return vec![];
    }
    if index.kind() != NODE_IDENT {
        return vec![];
    }
    if ident_text(key) != ident_text(index) {
        return vec![];
    }
    let at = node.range();
    let replacement = format!("inherit ({}) {};", set.text(), key.text());
    let message = "This assignment is better written with `inherit`";
    vec![Report::new(4, "Assignment instead of inherit from").suggest(at, message, at, replacement)]
}

// ---------------------------------------------------------------------------
// W05
// ---------------------------------------------------------------------------

fn legacy_let_syntax(node: Node<'_>) -> Vec<Report> {
    let has_body = attrpath_values(node).any(|apv| {
        apv_attrpath(apv)
            .and_then(|ap| attrs(ap).next())
            .and_then(|a| ident_text(a))
            == Some("body")
    });
    if !has_body {
        return vec![];
    }
    let mut replacement = String::from("rec {\n");
    for entry in entries(node) {
        replacement.push_str("  ");
        replacement.push_str(entry.text());
        replacement.push('\n');
    }
    replacement.push_str("}.body");
    let at = node.range();
    let message = "Prefer `rec` over undocumented `let` syntax";
    vec![Report::new(5, "Using undocumented `let` syntax").suggest(at, message, at, replacement)]
}

// ---------------------------------------------------------------------------
// W06
// ---------------------------------------------------------------------------

fn collapsible_let_in(node: Node<'_>) -> Vec<Report> {
    let body = match last_expr(node) {
        Some(b) => b,
        None => return vec![],
    };
    if body.kind() != NODE_LET_IN {
        return vec![];
    }
    let outer_let = match token(node, TOKEN_LET) {
        Some(t) => t,
        None => return vec![],
    };
    let outer_in = match token(node, TOKEN_IN) {
        Some(t) => t,
        None => return vec![],
    };
    let inner_let = match token(body, TOKEN_LET) {
        Some(t) => t,
        None => return vec![],
    };
    let inner_in = match token(body, TOKEN_IN) {
        Some(t) => t,
        None => return vec![],
    };
    let first_at = node.range();
    let second_at = body.range();
    let replacement = format!(
        "let{}{}in{}",
        text_between(node, outer_let, outer_in),
        text_between(body, inner_let, inner_in),
        text_after(body, inner_in)
    );
    let first_message = "This `let in` expression contains a nested `let in` expression";
    let second_message = "This `let in` expression is nested";
    vec![Report::new(6, "These let-in expressions are collapsible")
        .suggest(first_at, first_message, first_at, replacement)
        .diagnostic(second_at, second_message)]
}

// ---------------------------------------------------------------------------
// W07
// ---------------------------------------------------------------------------

fn eta_reduction(node: Node<'_>) -> Vec<Report> {
    let param = match lambda_param(node) {
        Some(p) => p,
        None => return vec![],
    };
    if param.kind() != NODE_IDENT_PARAM {
        return vec![];
    }
    let arg_ident = match param.first_child_of_kind(NODE_IDENT) {
        Some(i) => i,
        None => return vec![],
    };
    let arg_name = match ident_text(arg_ident) {
        Some(n) => n,
        None => return vec![],
    };
    let body = match lambda_body(node) {
        Some(b) => b,
        None => return vec![],
    };
    if body.kind() != NODE_APPLY {
        return vec![];
    }
    let func = match nth_expr(body, 0) {
        Some(f) => f,
        None => return vec![],
    };
    let value = match nth_expr(body, 1) {
        Some(v) => v,
        None => return vec![],
    };
    if value.kind() != NODE_IDENT || ident_text(value) != Some(arg_name) {
        return vec![];
    }
    if func.kind() != NODE_IDENT {
        return vec![];
    }
    // the function must not mention the argument
    if ident_text(func) == Some(arg_name) {
        return vec![];
    }
    let at = node.range();
    let replacement = func.text().to_string();
    let message = format!("Found eta-reduction: `{}`", replacement);
    vec![Report::new(7, "This function expression is eta reducible").suggest(at, message, at, replacement)]
}

// ---------------------------------------------------------------------------
// W08
// ---------------------------------------------------------------------------

fn paren_inner(paren: Node<'_>) -> Option<Node<'_>> {
    first_expr(paren)
}

fn useless_parens(node: Node<'_>) -> Vec<Report> {
    let report = Report::new(8, "These parentheses can be omitted");
    match node.kind() {
        NODE_ATTRPATH_VALUE => {
            let value = match apv_value(node) {
                Some(v) => v,
                None => return vec![],
            };
            if value.kind() != NODE_PAREN {
                return vec![];
            }
            let inner = match paren_inner(value) {
                Some(i) => i,
                None => return vec![],
            };
            let at = value.range();
            let message = "Useless parentheses around value in binding";
            vec![report.suggest(at, message, at, inner.text())]
        }
        NODE_LET_IN => {
            let body = match last_expr(node) {
                Some(b) => b,
                None => return vec![],
            };
            if body.kind() != NODE_PAREN {
                return vec![];
            }
            let inner = match paren_inner(body) {
                Some(i) => i,
                None => return vec![],
            };
            let at = body.range();
            let message = "Useless parentheses around body of `let` expression";
            vec![report.suggest(at, message, at, inner.text())]
        }
        NODE_PAREN => {
            // don't lint values of bindings or let bodies, handled above
            if let Some(parent) = node.parent() {
                if parent.kind() == NODE_ATTRPATH_VALUE {
                    return vec![];
                }
                if parent.kind() == NODE_LET_IN && last_expr(parent).map(|b| b.id) == Some(node.id)
                {
                    return vec![];
                }
            }
            let inner = match paren_inner(node) {
                Some(i) => i,
                None => return vec![],
            };
            if !matches!(
                inner.kind(),
                NODE_LIST | NODE_PAREN | NODE_STRING | NODE_ATTR_SET | NODE_SELECT | NODE_IDENT
            ) {
                return vec![];
            }
            if inner.kind() == NODE_SELECT && select_has_default(inner) {
                return vec![];
            }
            let at = node.range();
            let message = "Useless parentheses around primitive expression";
            vec![report.suggest(at, message, at, inner.text())]
        }
        _ => vec![],
    }
}

// ---------------------------------------------------------------------------
// W10
// ---------------------------------------------------------------------------

fn pattern_has_entries(node: Node<'_>) -> bool {
    node.children().any(|c| c.kind() == NODE_PAT_ENTRY)
}

fn pattern_bind(node: Node<'_>) -> Option<Node<'_>> {
    node.first_child_of_kind(NODE_PAT_BIND)
}

fn empty_pattern(node: Node<'_>) -> Vec<Report> {
    if pattern_has_entries(node) || pattern_bind(node).is_some() {
        return vec![];
    }
    let at = node.range();
    let message = "This pattern is empty, use `_` instead";
    vec![Report::new(10, "Found empty pattern in function argument").suggest(at, message, at, "_")]
}

// ---------------------------------------------------------------------------
// W11
// ---------------------------------------------------------------------------

fn redundant_pattern_bind(node: Node<'_>) -> Vec<Report> {
    if pattern_has_entries(node) {
        return vec![];
    }
    let bind = match pattern_bind(node) {
        Some(b) => b,
        None => return vec![],
    };
    if !has_token(node, TOKEN_ELLIPSIS) {
        return vec![];
    }
    let ident = match bind.first_child_of_kind(NODE_IDENT) {
        Some(i) => i,
        None => return vec![],
    };
    let at = node.range();
    let message = format!("This pattern bind is redundant, use `{}` instead", ident.text());
    vec![Report::new(11, "Found redundant pattern bind in function argument").suggest(
        at,
        message,
        at,
        ident.text(),
    )]
}

// ---------------------------------------------------------------------------
// W12
// ---------------------------------------------------------------------------

fn unquoted_uri(node: Node<'_>) -> Vec<Report> {
    if !node.tokens().any(|t| t.kind() == TOKEN_URI) {
        return vec![];
    }
    let at = node.range();
    let replacement = format!("\"{}\"", node.text());
    let message = "Consider quoting this URI expression";
    vec![Report::new(12, "Found unquoted URI expression").suggest(at, message, at, replacement)]
}

// ---------------------------------------------------------------------------
// W14
// ---------------------------------------------------------------------------

fn empty_inherit(node: Node<'_>) -> Vec<Report> {
    if inherit_from(node).is_some() {
        return vec![];
    }
    if inherit_attrs(node).next().is_some() {
        return vec![];
    }
    let at = node.range();
    // remove preceding whitespace as well
    let suggestion_at = match node.prev_sibling_or_token() {
        Some(NodeOrToken::Token(t)) if t.kind() == TOKEN_WHITESPACE => {
            TextRange::new(t.range().start, at.end)
        }
        _ => at,
    };
    let message = "Remove this empty `inherit` statement";
    vec![Report::new(14, "Found empty inherit statement").suggest(at, message, suggestion_at, "")]
}

// ---------------------------------------------------------------------------
// W17
// ---------------------------------------------------------------------------

fn deprecated_to_path(node: Node<'_>) -> Vec<Report> {
    let func = match nth_expr(node, 0) {
        Some(f) => f,
        None => return vec![],
    };
    let is_to_path = match func.kind() {
        NODE_IDENT => ident_text(func) == Some("toPath"),
        NODE_SELECT => {
            let set = select_expr(func).and_then(ident_text);
            let attrpath = select_attrpath(func);
            let mut parts = attrpath.map(|a| attrs(a).collect::<Vec<_>>()).unwrap_or_default();
            set == Some("builtins")
                && parts.len() == 1
                && ident_text(parts.remove(0)) == Some("toPath")
                && !select_has_default(func)
        }
        _ => false,
    };
    if !is_to_path {
        return vec![];
    }
    let at = node.range();
    let message = format!(
        "`{}` is deprecated, see `:doc builtins.toPath` within the REPL for more",
        func.text()
    );
    vec![Report::new(17, "Found usage of deprecated builtin toPath").diagnostic(at, message)]
}

// ---------------------------------------------------------------------------
// W18
// ---------------------------------------------------------------------------

fn bool_simplification(node: Node<'_>) -> Vec<Report> {
    if !has_token(node, TOKEN_INVERT) {
        return vec![];
    }
    let operand = match first_expr(node) {
        Some(o) => o,
        None => return vec![],
    };
    if operand.kind() != NODE_PAREN {
        return vec![];
    }
    let inner = match paren_inner(operand) {
        Some(i) => i,
        None => return vec![],
    };
    if inner.kind() != NODE_BIN_OP || !has_token(inner, TOKEN_EQUAL) {
        return vec![];
    }
    let lhs = match nth_expr(inner, 0) {
        Some(l) => l,
        None => return vec![],
    };
    let rhs = match nth_expr(inner, 1) {
        Some(r) => r,
        None => return vec![],
    };
    let at = node.range();
    let replacement = format!("{} != {}", lhs.text(), rhs.text());
    let message = "Try `!=` instead of `!(... == ...)`";
    vec![Report::new(18, "This boolean expression can be simplified").suggest(at, message, at, replacement)]
}

// ---------------------------------------------------------------------------
// W19
// ---------------------------------------------------------------------------

fn useless_has_attr(node: Node<'_>) -> Vec<Report> {
    let cond = match nth_expr(node, 0) {
        Some(c) => c,
        None => return vec![],
    };
    let body = match nth_expr(node, 1) {
        Some(b) => b,
        None => return vec![],
    };
    let else_body = match nth_expr(node, 2) {
        Some(e) => e,
        None => return vec![],
    };
    if cond.kind() != NODE_HAS_ATTR || body.kind() != NODE_SELECT {
        return vec![];
    }
    let cond_set = match first_expr(cond) {
        Some(s) => s,
        None => return vec![],
    };
    let cond_attrpath = match cond.first_child_of_kind(NODE_ATTRPATH) {
        Some(a) => a,
        None => return vec![],
    };
    let body_set = match select_expr(body) {
        Some(s) => s,
        None => return vec![],
    };
    let body_attrpath = match select_attrpath(body) {
        Some(a) => a,
        None => return vec![],
    };
    if select_has_default(body) {
        return vec![];
    }
    if cond_set.text() != body_set.text() || cond_attrpath.text() != body_attrpath.text() {
        return vec![];
    }
    let default = if matches!(
        else_body.kind(),
        NODE_IDENT | NODE_SELECT | NODE_STRING | NODE_LIST | NODE_ATTR_SET | NODE_PAREN
    ) {
        else_body.text().to_string()
    } else {
        format!("({})", else_body.text())
    };
    let replacement = format!("{} or {}", body.text(), default);
    let at = node.range();
    let message = format!("Consider using `{}` instead of this `if` expression", replacement);
    vec![Report::new(19, "This `if` expression can be simplified with `or`").suggest(at, message, at, replacement)]
}

// ---------------------------------------------------------------------------
// W20
// ---------------------------------------------------------------------------

fn repeated_keys(node: Node<'_>) -> Vec<Report> {
    if has_token(node, TOKEN_REC) {
        return vec![];
    }
    // group attrpath values by their first ident component, in order of appearance
    struct Group<'a> {
        name: String,
        entries: Vec<(Node<'a>, Node<'a>)>, // (attrpath, apv)
        invalid: bool,
    }
    let mut groups: Vec<Group> = Vec::new();
    for apv in attrpath_values(node) {
        let attrpath = match apv_attrpath(apv) {
            Some(a) => a,
            None => continue,
        };
        let comps: Vec<Node> = attrs(attrpath).collect();
        let first = match comps.first() {
            Some(f) => *f,
            None => continue,
        };
        let name = match ident_text(first) {
            Some(n) => n.to_string(),
            None => continue,
        };
        let idx = match groups.iter().position(|g| g.name == name) {
            Some(i) => i,
            None => {
                groups.push(Group { name: name.clone(), entries: Vec::new(), invalid: false });
                groups.len() - 1
            }
        };
        if comps.len() < 2 {
            groups[idx].invalid = true;
        } else {
            groups[idx].entries.push((attrpath, apv));
        }
    }
    let mut reports = Vec::new();
    for group in groups {
        if group.invalid || group.entries.len() < 3 {
            continue;
        }
        let first = group.entries[0].0;
        let second = group.entries[1].0;
        let third = group.entries[2].0;
        let rest: Vec<String> = group
            .entries
            .iter()
            .take(3)
            .map(|(attrpath, _)| {
                let comps: Vec<&str> = attrs(*attrpath).skip(1).map(|c| c.text()).collect();
                format!("{}=...;", comps.join("."))
            })
            .collect();
        let omitted = group.entries.len() - 3;
        let third_msg = if omitted > 0 {
            format!(
                "... and here (`{}` occurrences omitted). Try `{} = {{ {} }}` instead.",
                omitted,
                group.name,
                rest.join(" ")
            )
        } else {
            format!("... and here. Try `{} = {{ {} }}` instead.", group.name, rest.join(" "))
        };
        reports.push(
            Report::new(20, "Avoid repeated keys in attribute sets")
                .diagnostic(
                    first.range(),
                    format!("The key `{}` is first assigned here ...", group.name),
                )
                .diagnostic(second.range(), "... repeated here ...")
                .diagnostic(third.range(), third_msg),
        );
    }
    reports
}

// ---------------------------------------------------------------------------
// W23
// ---------------------------------------------------------------------------

fn is_empty_list(node: Node<'_>) -> bool {
    node.kind() == NODE_LIST && node.children().next().is_none()
}

fn empty_list_concat(node: Node<'_>) -> Vec<Report> {
    if !has_token(node, TOKEN_CONCAT) {
        return vec![];
    }
    let lhs = match nth_expr(node, 0) {
        Some(l) => l,
        None => return vec![],
    };
    let rhs = match nth_expr(node, 1) {
        Some(r) => r,
        None => return vec![],
    };
    let replacement = if is_empty_list(lhs) {
        rhs
    } else if is_empty_list(rhs) {
        lhs
    } else {
        return vec![];
    };
    let at = node.range();
    let message = "Concatenation with the empty list, `[]`, is a no-op";
    vec![Report::new(23, "Unnecessary concatenation with empty list").suggest(at, message, at, replacement.text())]
}
EOF
echo ok"}

