//! Lint definitions.

use crate::ast::*;
use crate::kinds::*;
use crate::syntax::{Node, NodeOrToken, TextRange};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Severity {
    Warn,
    Error,
}

#[derive(Clone, Debug)]
pub struct Suggestion {
    pub at: TextRange,
    pub fix: String,
}

#[derive(Clone, Debug)]
pub struct Diagnostic {
    pub at: TextRange,
    pub message: String,
    pub suggestion: Option<Suggestion>,
}

#[derive(Clone, Debug)]
pub struct Report {
    pub code: u32,
    pub note: &'static str,
    pub severity: Severity,
    pub diagnostics: Vec<Diagnostic>,
}

impl Report {
    pub fn new(code: u32, note: &'static str) -> Self {
        Report { code, note, severity: Severity::Warn, diagnostics: Vec::new() }
    }
    pub fn diagnostic(mut self, at: TextRange, message: impl Into<String>) -> Self {
        self.diagnostics.push(Diagnostic { at, message: message.into(), suggestion: None });
        self
    }
    pub fn suggest(
        mut self,
        at: TextRange,
        message: impl Into<String>,
        suggestion_at: TextRange,
        fix: impl Into<String>,
    ) -> Self {
        self.diagnostics.push(Diagnostic {
            at,
            message: message.into(),
            suggestion: Some(Suggestion { at: suggestion_at, fix: fix.into() }),
        });
        self
    }
    /// Range covered by this report (first diagnostic).
    pub fn range(&self) -> TextRange {
        let mut start = usize::MAX;
        let mut end = 0;
        for d in &self.diagnostics {
            start = start.min(d.at.start);
            end = end.max(d.at.end);
        }
        if start == usize::MAX {
            TextRange::new(0, 0)
        } else {
            TextRange::new(start, end)
        }
    }
}

pub struct LintInfo {
    pub code: u32,
    pub name: &'static str,
    pub note: &'static str,
    pub kinds: &'static [SyntaxKind],
    pub check: fn(Node<'_>) -> Vec<Report>,
}

pub static LINTS: &[LintInfo] = &[
    LintInfo {
        code: 1,
        name: "bool_comparison",
        note: "Unnecessary comparison with boolean",
        kinds: &[NODE_BIN_OP],
        check: bool_comparison,
    },
    LintInfo {
        code: 2,
        name: "empty_let_in",
        note: "Useless let-in expression",
        kinds: &[NODE_LET_IN],
        check: empty_let_in,
    },
    LintInfo {
        code: 3,
        name: "manual_inherit",
        note: "Assignment instead of inherit",
        kinds: &[NODE_ATTRPATH_VALUE],
        check: manual_inherit,
    },
    LintInfo {
        code: 4,
        name: "manual_inherit_from",
        note: "Assignment instead of inherit from",
        kinds: &[NODE_ATTRPATH_VALUE],
        check: manual_inherit_from,
    },
    LintInfo {
        code: 5,
        name: "legacy_let_syntax",
        note: "Using undocumented `let` syntax",
        kinds: &[NODE_LEGACY_LET],
        check: legacy_let_syntax,
    },
    LintInfo {
        code: 6,
        name: "collapsible_let_in",
        note: "These let-in expressions are collapsible",
        kinds: &[NODE_LET_IN],
        check: collapsible_let_in,
    },
    LintInfo {
        code: 7,
        name: "eta_reduction",
        note: "This function expression is eta reducible",
        kinds: &[NODE_LAMBDA],
