    },
    LintInfo {
        code: 8,
        name: "useless_parens",
        note: "These parentheses can be omitted",
        kinds: &[NODE_ATTRPATH_VALUE, NODE_LET_IN, NODE_PAREN],
        check: useless_parens,
    },
    LintInfo {
        code: 10,
        name: "empty_pattern",
        note: "Found empty pattern in function argument",
        kinds: &[NODE_PATTERN],
        check: empty_pattern,
    },
    LintInfo {
        code: 11,
        name: "redundant_pattern_bind",
        note: "Found redundant pattern bind in function argument",
        kinds: &[NODE_PATTERN],
        check: redundant_pattern_bind,
    },
    LintInfo {
        code: 12,
        name: "unquoted_uri",
        note: "Found unquoted URI expression",
        kinds: &[NODE_LITERAL],
        check: unquoted_uri,
    },
    LintInfo {
        code: 14,
        name: "empty_inherit",
        note: "Found empty inherit statement",
