impl Line {
    fn span(&self) -> (usize, usize) {
        (self.offset, self.offset + self.len)
    }
    fn contains(&self, offset: usize) -> bool {
        self.offset <= offset && offset < self.offset + self.len
    }
}

pub struct Source {
    lines: Vec<Line>,
    len: usize,
}

impl Source {
    pub fn from(s: &str) -> Self {
        let mut offset = 0;
        let lines: Vec<Line> = s
            .lines()
            .map(|line| {
                let l = Line {
                    offset,
                    len: line.chars().count() + 1,
                    chars: line.trim_end().to_owned(),
                };
                offset += l.len;
                l
            })
            .collect();
        Source { lines, len: offset }
    }

    fn line(&self, idx: usize) -> Option<&Line> {
        self.lines.get(idx)
    }

    fn get_offset_line(&self, offset: usize) -> Option<(&Line, usize, usize)> {
        if offset <= self.len {
            let idx = match self.lines.binary_search_by_key(&offset, |line| line.offset) {
                Ok(i) => i,
                Err(i) => i.saturating_sub(1),
            };
            let line = self.lines.get(idx)?;
            if offset < line.offset {
                return None;
            }
            Some((line, idx, offset - line.offset))
        } else {
            None
        }
    }

    fn get_line_range(&self, start: usize, end: usize) -> std::ops::Range<usize> {
        let s = self.get_offset_line(start).map_or(0, |(_, l, _)| l);
        let e = self
            .get_offset_line(end.saturating_sub(1).max(start))
            .map_or(self.lines.len(), |(_, l, _)| l + 1);
        s..e
    }
