                line_labels
                    .iter()
                    .filter(|ll| !ll.multi && ll.label.contains(line.offset + col))
                    .min_by_key(|ll| (-ll.label.priority, ll.label.len()))
            };

            // Margin
            write_margin(&mut w, idx, true, true, None, &line_labels, &margin_label);

            // Line
            for (col, c) in line.chars.chars().enumerate() {
                let color = match get_highlight(col) {
                    Some(highlight) => highlight.color,
                    None => UNIMPORTANT_COLOR,
                };
                let (c, width) = char_width(c, col);
                if c.is_whitespace() {
                    for _ in 0..width {
                        let _ = write!(w, "{}", paint_char(' ', color));
                    }
                } else {
                    let _ = write!(w, "{}", paint_char(c, color));
                }
            }
            let _ = writeln!(w);

            // Arrows
            for row in 0..line_labels.len() {
                let line_label = &line_labels[row];

                // Margin alternate
                write_margin(&mut w, idx, false, true, Some((row, false)), &line_labels, &margin_label);
                // Lines alternate
                let mut chars = line.chars.chars();
                for col in 0..arrow_len {
                    let width = chars.next().map_or(1, |c| char_width(c, col).1);

                    let vbar = get_vbar(col, row);
                    let underline = get_underline(col).filter(|_| row == 0);
                    let (c, tail): (String, String) = if let Some(vbar_ll) = vbar {
                        let (c, tail) = if underline.is_some() {
                            (draw.underbar, draw.underline)
                        } else {
                            (draw.vbar, ' ')
                        };
                        (paint_char(c, vbar_ll.label.color), paint_char(tail, vbar_ll.label.color))
                    } else if let Some(underline_ll) = underline {
                        (
                            paint_char(draw.underline, underline_ll.label.color),
                            paint_char(draw.underline, underline_ll.label.color),
                        )
                    } else {
                        (" ".to_string(), " ".to_string())
                    };

                    for i in 0..width {
                        let _ = write!(w, "{}", if i == 0 { &c } else { &tail });
                    }
                }
                let _ = writeln!(w);

                // Margin
                write_margin(&mut w, idx, false, true, Some((row, true)), &line_labels, &margin_label);
                // Lines
                let mut chars = line.chars.chars();
                for col in 0..arrow_len {
                    let width = chars.next().map_or(1, |c| char_width(c, col).1);

                    let is_hbar = (((col > line_label.col) ^ line_label.multi)
                        || (line_label.label.msg.is_some() && line_label.draw_msg && col > line_label.col))
                        && line_label.label.msg.is_some();
                    let (c, tail): (String, String) = if col == line_label.col
                        && line_label.label.msg.is_some()
                        && margin_label.as_ref().map_or(true, |m| !same(line_label.label, m.label))
                    {
                        (
                            paint_char(
                                if line_label.multi {
                                    if line_label.draw_msg {
                                        draw.mbot
                                    } else {
                                        draw.rbot
                                    }
                                } else {
                                    draw.lbot
                                },
                                line_label.label.color,
                            ),
                            paint_char(draw.hbar, line_label.label.color),
                        )
                    } else if let Some(vbar_ll) = get_vbar(col, row)
                        .filter(|_| col != line_label.col || line_label.label.msg.is_some())
                    {
                        if is_hbar {
                            (
                                paint_char(draw.hbar, line_label.label.color),
                                paint_char(draw.hbar, line_label.label.color),
                            )
                        } else {
                            (
                                paint_char(draw.vbar, vbar_ll.label.color),
                                paint_char(' ', line_label.label.color),
                            )
                        }
                    } else if is_hbar {
                        (
                            paint_char(draw.hbar, line_label.label.color),
                            paint_char(draw.hbar, line_label.label.color),
                        )
                    } else {
                        (" ".to_string(), " ".to_string())
                    };

                    if width > 0 {
                        let _ = write!(w, "{}", c);
                    }
                    for _ in 1..width {
                        let _ = write!(w, "{}", tail);
                    }
                }
                if line_label.draw_msg {
                    let _ = write!(w, " {}", line_label.label.msg.as_deref().unwrap_or(""));
                }
                let _ = writeln!(w);
            }
        }

        // Tail of report
        let final_margin = format!("{}{}", draw.hbar.to_string().repeat(line_no_width + 2), draw.rbot);
        let _ = writeln!(w, "{}", paint(&final_margin, MARGIN_COLOR));

        w
    }
}
EOF
echo ok"}

actions.command:
cd /workspace && cat > src/render.rs <<'EOF'
//! Pretty report rendering (terminal output with source excerpts).

use std::fmt::Write;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Color {
    Fixed(u8),
    Red,
    Yellow,
    Magenta,
    Cyan,
}

impl Color {
    fn code(&self) -> String {
        match self {
            Color::Fixed(n) => format!("\x1b[38;5;{}m", n),
            Color::Red => "\x1b[31m".to_string(),
            Color::Yellow => "\x1b[33m".to_string(),
            Color::Magenta => "\x1b[35m".to_string(),
            Color::Cyan => "\x1b[36m".to_string(),
        }
    }
}

pub fn paint(s: &str, color: Option<Color>) -> String {
    match color {
        Some(c) => format!("{}{}\x1b[0m", c.code(), s),
        None => s.to_string(),
    }
}

fn paint_char(c: char, color: Option<Color>) -> String {
    let mut s = String::new();
    s.push(c);
    paint(&s, color)
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum ReportKind {
    Error,
    Warning,
}

#[derive(Clone)]
pub struct Label {
    pub start: usize,
    pub end: usize,
    pub msg: Option<String>,
    pub color: Option<Color>,
    pub order: i32,
    pub priority: i32,
}

impl Label {
    fn len(&self) -> usize {
        self.end.saturating_sub(self.start)
    }
    fn last_offset(&self) -> usize {
        self.end.saturating_sub(1).max(self.start)
    }
    fn contains(&self, offset: usize) -> bool {
        self.start <= offset && offset < self.end
    }
}

pub struct Report {
    pub kind: ReportKind,
    pub code: Option<String>,
    pub msg: Option<String>,
    pub location: usize,
    pub labels: Vec<Label>,
}

struct Line {
    offset: usize,
    len: usize,
    chars: String,
}

impl Line {
    fn span(&self) -> (usize, usize) {
        (self.offset, self.offset + self.len)
    }
    fn contains(&self, offset: usize) -> bool {
        self.offset <= offset && offset < self.offset + self.len
    }
}

pub struct Source {
    lines: Vec<Line>,
    len: usize,
}

impl Source {
    pub fn from(s: &str) -> Self {
        let mut offset = 0;
        let lines: Vec<Line> = s
            .lines()
            .map(|line| {
                let l = Line {
                    offset,
                    len: line.chars().count() + 1,
                    chars: line.trim_end().to_owned(),
                };
                offset += l.len;
                l
            })
            .collect();
        Source { lines, len: offset }
    }

    fn line(&self, idx: usize) -> Option<&Line> {
        self.lines.get(idx)
    }

    fn get_offset_line(&self, offset: usize) -> Option<(&Line, usize, usize)> {
        if offset <= self.len {
            let idx = match self.lines.binary_search_by_key(&offset, |line| line.offset) {
                Ok(i) => i,
                Err(i) => i.saturating_sub(1),
            };
            let line = self.lines.get(idx)?;
            if offset < line.offset {
                return None;
            }
            Some((line, idx, offset - line.offset))
        } else {
            None
        }
    }

    fn get_line_range(&self, start: usize, end: usize) -> std::ops::Range<usize> {
        let s = self.get_offset_line(start).map_or(0, |(_, l, _)| l);
        let e = self
            .get_offset_line(end.saturating_sub(1).max(start))
            .map_or(self.lines.len(), |(_, l, _)| l + 1);
        s..e
    }
}

struct Characters {
    hbar: char,
    vbar: char,
    xbar: char,
    vbar_break: char,
    uarrow: char,
    rarrow: char,
    ltop: char,
    mtop: char,
    rtop: char,
    lbot: char,
    rbot: char,
    mbot: char,
    lbox: char,
    rbox: char,
    lcross: char,
    rcross: char,
    underbar: char,
    underline: char,
}

fn unicode_chars() -> Characters {
    Characters {
        hbar: '─',
        vbar: '│',
        xbar: '┼',
        vbar_break: '·',
        uarrow: '▲',
        rarrow: '▶',
        ltop: '╭',
        mtop: '┬',
        rtop: '╮',
        lbot: '╰',
        rbot: '╯',
        mbot: '┴',
        lbox: '[',
        rbox: ']',
        lcross: '├',
        rcross: '┤',
        underbar: '┬',
        underline: '─',
    }
}

const TAB_WIDTH: usize = 4;

fn char_width(c: char, col: usize) -> (char, usize) {
    match c {
        '\t' => {
            let tab_end = (col / TAB_WIDTH + 1) * TAB_WIDTH;
            (' ', tab_end - col)
        }
        c if c.is_whitespace() => (' ', 1),
        _ => (c, 1),
    }
}

const MARGIN_COLOR: Option<Color> = Some(Color::Fixed(246));
const UNIMPORTANT_COLOR: Option<Color> = Some(Color::Fixed(249));

#[derive(Clone, Copy, PartialEq)]
enum LabelKind {
    Inline,
    Multiline,
}

struct LineLabel<'a> {
    col: usize,
    label: &'a Label,
    multi: bool,
    draw_msg: bool,
}

fn same<'a>(a: &'a Label, b: &'a Label) -> bool {
    std::ptr::eq(a, b)
}

impl Report {
    pub fn write(&self, src_name: &str, src: &Source) -> String {
        let mut w = String::new();
        let draw = unicode_chars();
        let _ = &draw.mtop;
        let _ = &draw.rtop;
        let _ = &draw.rcross;
        let _ = &draw.vbar_break;
        let _ = &draw.uarrow;

        // --- Header ---
        let code = self.code.as_ref().map(|c| format!("[{}] ", c)).unwrap_or_default();
        let kind_str = match self.kind {
            ReportKind::Error => "Error",
            ReportKind::Warning => "Warning",
        };
        let id = format!("{}{}:", code, kind_str);
        let kind_color = match self.kind {
            ReportKind::Error => Some(Color::Red),
            ReportKind::Warning => Some(Color::Yellow),
        };
        let _ = writeln!(
            w,
            "{} {}",
            paint(&id, kind_color),
            self.msg.as_deref().unwrap_or("")
        );

        // Single source group covering all labels
        if self.labels.is_empty() {
            return w;
        }
        let mut span_start = usize::MAX;
        let mut span_end = 0;
        let mut label_kinds = Vec::new();
        for label in &self.labels {
            span_start = span_start.min(label.start);
            span_end = span_end.max(label.end);
            let start_line = src.get_offset_line(label.start).map(|(_, l, _)| l);
            let end_line = src.get_offset_line(label.last_offset()).map(|(_, l, _)| l);
            let kind = if start_line == end_line { LabelKind::Inline } else { LabelKind::Multiline };
            label_kinds.push(kind);
        }

        let line_range = src.get_line_range(span_start, span_end);

        // Line number maximum width
        let line_no_width = {
            let end = line_range.end as u32;
            (1..).map(|x| 10u32.checked_pow(x).unwrap_or(u32::MAX)).take_while(|x| end / x != 0).count() + 1
        };

        // File name & reference
        let (line_no, col_no) = src
            .get_offset_line(self.location)
            .map(|(_, idx, col)| (format!("{}", idx + 1), format!("{}", col + 1)))
            .unwrap_or_else(|| ("?".to_string(), "?".to_string()));
        let line_ref = format!(":{}:{}", line_no, col_no);
        let _ = writeln!(
            w,
            "{}{}{}{}{}{}{}",
            " ".repeat(line_no_width + 2),
            paint_char(draw.ltop, MARGIN_COLOR),
            paint_char(draw.hbar, MARGIN_COLOR),
            paint_char(draw.lbox, MARGIN_COLOR),
            src_name,
            line_ref,
            paint_char(draw.rbox, MARGIN_COLOR),
        );
        let _ = writeln!(w, "{}{}", " ".repeat(line_no_width + 2), paint_char(draw.vbar, MARGIN_COLOR));

        // Generate a list of multi-line labels
        let mut multi_labels: Vec<&Label> = Vec::new();
        for (i, label) in self.labels.iter().enumerate() {
            if label_kinds[i] == LabelKind::Multiline {
                multi_labels.push(label);
            }
        }
        // Sort multiline labels by length
        multi_labels.sort_by_key(|m| -(m.len() as isize));

        let write_margin = |w: &mut String,
                            idx: usize,
                            is_line: bool,
                            draw_labels: bool,
                            report_row: Option<(usize, bool)>,
                            line_labels: &[LineLabel],
                            margin_label: &Option<LineLabel>| {
            let line_no_margin = if is_line {
                let line_no = format!("{}", idx + 1);
                format!(
                    "{}{} {}",
                    " ".repeat(line_no_width - line_no.chars().count()),
                    line_no,
                    draw.vbar
                )
            } else {
                format!("{}{}", " ".repeat(line_no_width + 1), draw.vbar_break)
            };
            let _ = write!(w, " {} ", paint(&line_no_margin, MARGIN_COLOR));

            // Multi-line margins
            if draw_labels {
                let ncols = multi_labels.len() + (if !multi_labels.is_empty() { 1 } else { 0 });
                for col in 0..ncols {
                    let mut corner: Option<(&Label, bool)> = None;
                    let mut hbar: Option<&Label> = None;
                    let mut vbar: Option<&Label> = None;
                    let mut margin_ptr: Option<(&LineLabel, bool)> = None;

                    let multi_label = multi_labels.get(col).copied();
                    let line_span = match src.line(idx) {
                        Some(l) => l.span(),
                        None => (0, 0),
                    };

                    let upto = (col + 1).min(multi_labels.len());
                    for (i, label) in multi_labels[0..upto].iter().enumerate() {
                        let label: &Label = *label;
                        let margin = margin_label.as_ref().filter(|m| same(label, m.label));

                        if label.start <= line_span.1 && label.end > line_span.0 {
                            let is_parent = i != col;
                            let is_start = line_span.0 <= label.start && label.start < line_span.1;
                            let is_end =
                                line_span.0 <= label.last_offset() && label.last_offset() < line_span.1;

                            if let Some(margin) = margin.filter(|_| is_line) {
                                margin_ptr = Some((margin, is_start));
                            } else if !is_start && (!is_end || is_line) {
                                if vbar.is_none() && !is_parent {
                                    vbar = Some(label);
                                }
                            } else if let Some((report_row, is_arrow)) = report_row {
                                let label_row = line_labels
                                    .iter()
                                    .enumerate()
                                    .find(|(_, l)| same(label, l.label))
                                    .map_or(0, |(r, _)| r);
                                if report_row == label_row {
                                    if let Some(margin) = margin {
                                        vbar = if col == i { Some(margin.label) } else { None };
                                        if is_start {
                                            continue;
                                        }
                                    }

                                    if is_arrow {
                                        hbar = Some(label);
                                        if !is_parent {
                                            corner = Some((label, is_start));
                                        }
                                    } else if !is_start {
                                        if vbar.is_none() && !is_parent {
                                            vbar = Some(label);
                                        }
                                    }
                                } else if vbar.is_none()
                                    && !is_parent
                                    && (is_start ^ (report_row < label_row))
                                {
                                    vbar = Some(label);
                                }
                            }
                        }
                    }

                    if let (Some((margin, _)), true) = (margin_ptr, is_line) {
                        let is_col = multi_label.map_or(false, |ml| same(ml, margin.label));
                        let is_limit = col + 1 == multi_labels.len();
                        if !is_col && !is_limit {
                            if hbar.is_none() {
                                hbar = Some(margin.label);
                            }
                        }
                    }

                    hbar = hbar.filter(|l| {
                        margin_label.as_ref().map_or(true, |margin| !same(margin.label, l)) || !is_line
                    });

                    let (a, b): (String, String) = if let Some((label, is_start)) = corner {
                        (
                            paint_char(if is_start { draw.ltop } else { draw.lbot }, label.color),
                            paint_char(draw.hbar, label.color),
                        )
                    } else if let Some(label) = hbar.filter(|_| vbar.is_some() && false) {
                        (paint_char(draw.xbar, label.color), paint_char(draw.hbar, label.color))
                    } else if let Some(label) = hbar {
                        (paint_char(draw.hbar, label.color), paint_char(draw.hbar, label.color))
                    } else if let Some(label) = vbar {
                        (paint_char(draw.vbar, label.color), " ".to_string())
                    } else if let (Some((margin, is_start)), true) = (margin_ptr, is_line) {
                        let is_col = multi_label.map_or(false, |ml| same(ml, margin.label));
                        let is_limit = col == multi_labels.len();
                        (
                            paint_char(
                                if is_limit {
                                    draw.rarrow
                                } else if is_col {
                                    if is_start {
                                        draw.ltop
                                    } else {
                                        draw.lcross
                                    }
                                } else {
                                    draw.hbar
                                },
                                margin.label.color,
                            ),
                            paint_char(if !is_limit { draw.hbar } else { ' ' }, margin.label.color),
                        )
                    } else {
                        (" ".to_string(), " ".to_string())
                    };
                    let _ = write!(w, "{}", a);
                    let _ = write!(w, "{}", b);
                }
            }
        };

        for idx in line_range {
            let line = match src.line(idx) {
                Some(l) => l,
                None => continue,
            };

            let margin_label: Option<LineLabel> = multi_labels
                .iter()
                .filter_map(|label| {
                    let label: &Label = *label;
                    let is_start = line.contains(label.start);
                    let is_end = line.contains(label.last_offset());
                    if is_start {
                        Some(LineLabel {
                            col: label.start - line.offset,
                            label,
                            multi: true,
                            draw_msg: false,
                        })
                    } else if is_end {
                        Some(LineLabel {
                            col: label.last_offset() - line.offset,
                            label,
                            multi: true,
                            draw_msg: true,
                        })
                    } else {
                        None
                    }
                })
                .min_by_key(|ll| (ll.col, !ll.label.start));

            // Generate a list of labels for this line, along with their label columns
            let mut line_labels: Vec<LineLabel> = multi_labels
                .iter()
                .filter_map(|label| {
                    let label: &Label = *label;
                    let is_start = line.contains(label.start);
                    let is_end = line.contains(label.last_offset());
                    if is_start && margin_label.as_ref().map_or(true, |m| !same(label, m.label)) {
                        Some(LineLabel {
                            col: label.start - line.offset,
                            label,
                            multi: true,
                            draw_msg: false,
                        })
                    } else if is_end {
                        Some(LineLabel {
                            col: label.last_offset() - line.offset,
                            label,
                            multi: true,
                            draw_msg: true,
                        })
                    } else {
                        None
                    }
                })
                .collect();

            for (i, label) in self.labels.iter().enumerate() {
                if label.start >= line.span().0
                    && label.end <= line.span().1
                    && label_kinds[i] == LabelKind::Inline
                {
                    line_labels.push(LineLabel {
                        col: ((label.start + label.end) / 2).max(label.start) - line.offset,
                        label,
                        multi: false,
                        draw_msg: true,
                    });
                }
            }

            // Skip this line if we don't have labels for it
            if line_labels.is_empty() && margin_label.is_none() {
                continue;
            }

            // Sort the labels by their columns
            line_labels.sort_by_key(|ll| (ll.label.order, ll.col, !ll.label.start));

            // Determine label bounds so we know where to put error messages
            let arrow_end_space = 2;
            let arrow_len = line_labels.iter().fold(0, |l, ll| {
                if ll.multi {
                    line.len
                } else {
                    l.max(ll.label.end.saturating_sub(line.offset))
                }
            }) + arrow_end_space;

            // Should we draw a vertical bar as part of a label arrow on this line?
            let get_vbar = |col: usize, row: usize| -> Option<&LineLabel> {
                line_labels
                    .iter()
                    .enumerate()
                    .filter(|(_, ll)| {
                        ll.label.msg.is_some()
                            && margin_label.as_ref().map_or(true, |m| !same(ll.label, m.label))
                    })
                    .find(|(j, ll)| ll.col == col && row <= *j)
                    .map(|(_, ll)| ll)
            };

            let get_highlight = |col: usize| -> Option<&Label> {
                margin_label
                    .iter()
                    .map(|ll| ll.label)
                    .chain(multi_labels.iter().copied())
                    .chain(line_labels.iter().map(|l| l.label))
                    .filter(|l| l.contains(line.offset + col))
                    .min_by_key(|l| (-l.priority, l.len()))
            };

            let get_underline = |col: usize| -> Option<&LineLabel> {
                line_labels
                    .iter()
                    .filter(|ll| !ll.multi && ll.label.contains(line.offset + col))
                    .min_by_key(|ll| (-ll.label.priority, ll.label.len()))
            };

            // Margin
            write_margin(&mut w, idx, true, true, None, &line_labels, &margin_label);

            // Line
            for (col, c) in line.chars.chars().enumerate() {
                let color = match get_highlight(col) {
                    Some(highlight) => highlight.color,
                    None => UNIMPORTANT_COLOR,
                };
                let (c, width) = char_width(c, col);
                if c.is_whitespace() {
                    for _ in 0..width {
                        let _ = write!(w, "{}", paint_char(' ', color));
                    }
                } else {
                    let _ = write!(w, "{}", paint_char(c, color));
                }
            }
            let _ = writeln!(w);

            // Arrows
            for row in 0..line_labels.len() {
                let line_label = &line_labels[row];

                // Margin alternate
                write_margin(&mut w, idx, false, true, Some((row, false)), &line_labels, &margin_label);
                // Lines alternate
                let mut chars = line.chars.chars();
                for col in 0..arrow_len {
                    let width = chars.next().map_or(1, |c| char_width(c, col).1);

                    let vbar = get_vbar(col, row);
                    let underline = get_underline(col).filter(|_| row == 0);
                    let (c, tail): (String, String) = if let Some(vbar_ll) = vbar {
                        let (c, tail) = if underline.is_some() {
                            (draw.underbar, draw.underline)
                        } else {
                            (draw.vbar, ' ')
                        };
                        (paint_char(c, vbar_ll.label.color), paint_char(tail, vbar_ll.label.color))
                    } else if let Some(underline_ll) = underline {
                        (
                            paint_char(draw.underline, underline_ll.label.color),
                            paint_char(draw.underline, underline_ll.label.color),
                        )
                    } else {
                        (" ".to_string(), " ".to_string())
                    };

                    for i in 0..width {
                        let _ = write!(w, "{}", if i == 0 { &c } else { &tail });
                    }
                }
                let _ = writeln!(w);

                // Margin
                write_margin(&mut w, idx, false, true, Some((row, true)), &line_labels, &margin_label);
                // Lines
                let mut chars = line.chars.chars();
                for col in 0..arrow_len {
                    let width = chars.next().map_or(1, |c| char_width(c, col).1);

                    let is_hbar = (((col > line_label.col) ^ line_label.multi)
                        || (line_label.label.msg.is_some() && line_label.draw_msg && col > line_label.col))
                        && line_label.label.msg.is_some();
                    let (c, tail): (String, String) = if col == line_label.col
                        && line_label.label.msg.is_some()
                        && margin_label.as_ref().map_or(true, |m| !same(line_label.label, m.label))
                    {
                        (
                            paint_char(
                                if line_label.multi {
                                    if line_label.draw_msg {
                                        draw.mbot
                                    } else {
                                        draw.rbot
                                    }
                                } else {
                                    draw.lbot
                                },
                                line_label.label.color,
                            ),
                            paint_char(draw.hbar, line_label.label.color),
                        )
                    } else if let Some(vbar_ll) = get_vbar(col, row)
                        .filter(|_| col != line_label.col || line_label.label.msg.is_some())
                    {
                        if is_hbar {
                            (
                                paint_char(draw.hbar, line_label.label.color),
                                paint_char(draw.hbar, line_label.label.color),
                            )
                        } else {
                            (
                                paint_char(draw.vbar, vbar_ll.label.color),
                                paint_char(' ', line_label.label.color),
                            )
                        }
                    } else if is_hbar {
                        (
                            paint_char(draw.hbar, line_label.label.color),
                            paint_char(draw.hbar, line_label.label.color),
                        )
                    } else {
                        (" ".to_string(), " ".to_string())
                    };

                    if width > 0 {
                        let _ = write!(w, "{}", c);
                    }
                    for _ in 1..width {
                        let _ = write!(w, "{}", tail);
                    }
                }
                if line_label.draw_msg {
                    let _ = write!(w, " {}", line_label.label.msg.as_deref().unwrap_or(""));
                }
                let _ = writeln!(w);
            }
        }

        // Tail of report
        let final_margin = format!("{}{}", draw.hbar.to_string().repeat(line_no_width + 2), draw.rbot);
        let _ = writeln!(w, "{}", paint(&final_margin, MARGIN_COLOR));

        w
    }
}
