//! Line based diffing with unified output.

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DiffOp {
    Equal { old_index: usize, new_index: usize, len: usize },
    Delete { old_index: usize, old_len: usize, new_index: usize },
    Insert { old_index: usize, new_index: usize, new_len: usize },
}

struct V {
    offset: isize,
    v: Vec<usize>,
}

impl V {
    fn new(max_d: usize) -> Self {
        V { offset: max_d as isize, v: vec![0; 2 * max_d] }
    }
    fn get(&self, k: isize) -> usize {
        self.v[(k + self.offset) as usize]
    }
    fn set(&mut self, k: isize, v: usize) {
        self.v[(k + self.offset) as usize] = v;
    }
}

fn max_d(len1: usize, len2: usize) -> usize {
    (len1 + len2 + 1) / 2 + 1
}

fn common_prefix_len<T: PartialEq>(old: &[T], old_range: (usize, usize), new: &[T], new_range: (usize, usize)) -> usize {
    let mut n = 0;
    let (mut i, mut j) = (old_range.0, new_range.0);
    while i < old_range.1 && j < new_range.1 && old[i] == new[j] {
        n += 1;
        i += 1;
        j += 1;
    }
    n
}

fn common_suffix_len<T: PartialEq>(old: &[T], old_range: (usize, usize), new: &[T], new_range: (usize, usize)) -> usize {
    let mut n = 0;
    let (mut i, mut j) = (old_range.1, new_range.1);
    while i > old_range.0 && j > new_range.0 && old[i - 1] == new[j - 1] {
        n += 1;
        i -= 1;
        j -= 1;
    }
    n
}

fn find_middle_snake<T: PartialEq>(
    old: &[T],
    old_range: (usize, usize),
    new: &[T],
    new_range: (usize, usize),
    vf: &mut V,
    vb: &mut V,
) -> Option<(usize, usize)> {
    let n = old_range.1 - old_range.0;
    let m = new_range.1 - new_range.0;

    let delta = n as isize - m as isize;
    let odd = delta & 1 == 1;

    vf.set(1, 0);
    vb.set(1, 0);

    let d_max = max_d(n, m);

    for d in 0..d_max as isize {
        // Forward path
        let mut k = d;
        while k >= -d {
            let mut x = if k == -d || (k != d && vf.get(k - 1) < vf.get(k + 1)) {
                vf.get(k + 1)
            } else {
                vf.get(k - 1) + 1
            };
            let y = (x as isize - k) as usize;

            let (x0, y0) = (x, y);
            if x < n && y < m {
                let advance = common_prefix_len(
                    old,
                    (old_range.0 + x, old_range.1),
                    new,
                    (new_range.0 + y, new_range.1),
                );
                x += advance;
            }

            vf.set(k, x);

            if odd && (k - delta).abs() <= (d - 1) {
                if vf.get(k) + vb.get(-(k - delta)) >= n {
                    return Some((x0 + old_range.0, y0 + new_range.0));
                }
            }
            k -= 2;
        }

        // Backward path
        let mut k = d;
        while k >= -d {
            let mut x = if k == -d || (k != d && vb.get(k - 1) < vb.get(k + 1)) {
                vb.get(k + 1)
            } else {
                vb.get(k - 1) + 1
            };
            let mut y = (x as isize - k) as usize;

            if x < n && y < m {
                let advance = common_suffix_len(
                    old,
                    (old_range.0, old_range.0 + n - x),
                    new,
                    (new_range.0, new_range.0 + m - y),
                );
                x += advance;
                y += advance;
            }

            vb.set(k, x);

            if !odd && (k - delta).abs() <= d {
                if vb.get(k) + vf.get(-(k - delta)) >= n {
                    return Some((n - x + old_range.0, m - y + new_range.0));
                }
            }
            k -= 2;
        }
    }

    None
}

fn conquer<T: PartialEq>(
    ops: &mut Vec<DiffOp>,
    old: &[T],
    mut old_range: (usize, usize),
    new: &[T],
    mut new_range: (usize, usize),
    vf: &mut V,
    vb: &mut V,
) {
    // Check for common prefix
    let common_prefix_len = common_prefix_len(old, old_range, new, new_range);
    if common_prefix_len > 0 {
        ops.push(DiffOp::Equal { old_index: old_range.0, new_index: new_range.0, len: common_prefix_len });
    }
    old_range.0 += common_prefix_len;
    new_range.0 += common_prefix_len;

    // Check for common suffix
    let common_suffix_len = common_suffix_len(old, old_range, new, new_range);
    let common_suffix = (old_range.1 - common_suffix_len, new_range.1 - common_suffix_len);
    old_range.1 -= common_suffix_len;
    new_range.1 -= common_suffix_len;

    let old_empty = old_range.0 >= old_range.1;
    let new_empty = new_range.0 >= new_range.1;

    if old_empty && new_empty {
        // nothing
    } else if new_empty {
        ops.push(DiffOp::Delete { old_index: old_range.0, old_len: old_range.1 - old_range.0, new_index: new_range.0 });
    } else if old_empty {
        ops.push(DiffOp::Insert { old_index: old_range.0, new_index: new_range.0, new_len: new_range.1 - new_range.0 });
    } else if let Some((x_start, y_start)) = find_middle_snake(old, old_range, new, new_range, vf, vb) {
        let (old_a, old_b) = ((old_range.0, x_start), (x_start, old_range.1));
        let (new_a, new_b) = ((new_range.0, y_start), (y_start, new_range.1));
        conquer(ops, old, old_a, new, new_a, vf, vb);
        conquer(ops, old, old_b, new, new_b, vf, vb);
    } else {
        ops.push(DiffOp::Delete { old_index: old_range.0, old_len: old_range.1 - old_range.0, new_index: new_range.0 });
        ops.push(DiffOp::Insert { old_index: old_range.0, new_index: new_range.0, new_len: new_range.1 - new_range.0 });
    }

    if common_suffix_len > 0 {
        ops.push(DiffOp::Equal { old_index: common_suffix.0, new_index: common_suffix.1, len: common_suffix_len });
    }
}

pub fn myers_diff<T: PartialEq>(old: &[T], new: &[T]) -> Vec<DiffOp> {
    let max_d = max_d(old.len(), new.len());
    let mut vb = V::new(max_d);
    let mut vf = V::new(max_d);
    let mut ops = Vec::new();
    conquer(&mut ops, old, (0, old.len()), new, (0, new.len()), &mut vf, &mut vb);
    ops
}

/// Split text into lines, keeping the line terminators.
pub fn split_lines(s: &str) -> Vec<&str> {
    let mut out = Vec::new();
    let mut start = 0;
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'\n' {
            out.push(&s[start..=i]);
            start = i + 1;
        } else if bytes[i] == b'\r' {
            if i + 1 < bytes.len() && bytes[i + 1] == b'\n' {
                out.push(&s[start..i + 2]);
                i += 1;
                start = i + 1;
            } else {
                out.push(&s[start..=i]);
                start = i + 1;
            }
        }
        i += 1;
    }
    if start < s.len() {
        out.push(&s[start..]);
    }
    out
}

fn group_diff_ops(mut ops: Vec<DiffOp>, n: usize) -> Vec<Vec<DiffOp>> {
    if ops.is_empty() {
        return vec![];
    }
    let mut pending_group = Vec::new();
    let mut rv = Vec::new();

    if let Some(DiffOp::Equal { old_index, new_index, len }) = ops.first_mut() {
        let offset = (*len).saturating_sub(n);
        *old_index += offset;
        *new_index += offset;
        *len -= offset;
    }

    if let Some(DiffOp::Equal { len, .. }) = ops.last_mut() {
        *len -= (*len).saturating_sub(n);
    }

    for op in ops.into_iter() {
        if let DiffOp::Equal { old_index, new_index, len } = op {
            // End the current group and start a new one whenever
            // there is a large range with no changes.
            if len > n * 2 {
                pending_group.push(DiffOp::Equal { old_index, new_index, len: n });
                rv.push(pending_group);
                let offset = len.saturating_sub(n);
                pending_group = vec![DiffOp::Equal {
                    old_index: old_index + offset,
                    new_index: new_index + offset,
                    len: len - offset,
                }];
                continue;
            }
        }
        pending_group.push(op);
    }

    match &pending_group[..] {
        &[] | &[DiffOp::Equal { .. }] => {}
        _ => rv.push(pending_group),
    }

    rv
}

fn hunk_range(start: usize, len: usize) -> String {
    let mut beginning = start + 1;
    if len == 1 {
        format!("{}", beginning)
    } else {
        if len == 0 {
            beginning -= 1;
        }
        format!("{},{}", beginning, len)
    }
}

/// Produce a unified diff (context radius 4) between old and new text.
pub fn unified_diff(old: &str, new: &str, old_name: &str, new_name: &str) -> String {
    let old_lines = split_lines(old);
    let new_lines = split_lines(new);
    let ops = myers_diff(&old_lines, &new_lines);
    let groups = group_diff_ops(ops, 4);
    let mut out = String::new();
    if groups.is_empty() {
        return out;
    }
    out.push_str(&format!("--- {}\n+++ {}\n", old_name, new_name));
    for group in groups {
        // compute ranges
        let mut old_start = usize::MAX;
        let mut old_end = 0;
        let mut new_start = usize::MAX;
        let mut new_end = 0;
        for op in &group {
            match *op {
                DiffOp::Equal { old_index, new_index, len } => {
                    old_start = old_start.min(old_index);
                    old_end = old_end.max(old_index + len);
                    new_start = new_start.min(new_index);
                    new_end = new_end.max(new_index + len);
                }
                DiffOp::Delete { old_index, old_len, new_index } => {
                    old_start = old_start.min(old_index);
                    old_end = old_end.max(old_index + old_len);
                    new_start = new_start.min(new_index);
                    new_end = new_end.max(new_index);
                }
                DiffOp::Insert { old_index, new_index, new_len } => {
                    old_start = old_start.min(old_index);
                    old_end = old_end.max(old_index);
                    new_start = new_start.min(new_index);
                    new_end = new_end.max(new_index + new_len);
                }
            }
        }
        out.push_str(&format!(
            "@@ -{} +{} @@\n",
            hunk_range(old_start, old_end - old_start),
            hunk_range(new_start, new_end - new_start)
        ));
        let mut emit = |tag: char, line: &str| {
            out.push(tag);
            out.push_str(line);
            if !line.ends_with('\n') {
                out.push('\n');
                out.push_str("\\ No newline at end of file\n");
            }
        };
        for op in &group {
            match *op {
                DiffOp::Equal { old_index, len, .. } => {
                    for i in 0..len {
                        emit(' ', old_lines[old_index + i]);
                    }
                }
                DiffOp::Delete { old_index, old_len, .. } => {
                    for i in 0..old_len {
                        emit('-', old_lines[old_index + i]);
                    }
                }
                DiffOp::Insert { new_index, new_len, .. } => {
                    for i in 0..new_len {
                        emit('+', new_lines[new_index + i]);
                    }
                }
            }
        }
    }
    out
}
