                }];
                continue;
            }
        }
        pending_group.push(op);
    }

    match &pending_group[..] {
        &[] | &[DiffOp::Equal { .. }] => {}
        _ => rv.push(pending_group),
    }

    rv
}

fn hunk_range(start: usize, len: usize) -> String {
    let mut beginning = start + 1;
    if len == 1 {
        format!("{}", beginning)
    } else {
        if len == 0 {
            beginning -= 1;
        }
        format!("{},{}", beginning, len)
    }
}

/// Produce a unified diff (context radius 4) between old and new text.
pub fn unified_diff(old: &str, new: &str, old_name: &str, new_name: &str) -> String {
    let old_lines = split_lines(old);
    let new_lines = split_lines(new);
    let ops = myers_diff(&old_lines, &new_lines);
    let groups = group_diff_ops(ops, 4);
    let mut out = String::new();
    if groups.is_empty() {
        return out;
    }
    out.push_str(&format!("--- {}\n+++ {}\n", old_name, new_name));
    for group in groups {
        // compute ranges
        let mut old_start = usize::MAX;
        let mut old_end = 0;
        let mut new_start = usize::MAX;
        let mut new_end = 0;
        for op in &group {
            match *op {
                DiffOp::Equal { old_index, new_index, len } => {
                    old_start = old_start.min(old_index);
                    old_end = old_end.max(old_index + len);
                    new_start = new_start.min(new_index);
                    new_end = new_end.max(new_index + len);
                }
                DiffOp::Delete { old_index, old_len, new_index } => {
                    old_start = old_start.min(old_index);
                    old_end = old_end.max(old_index + old_len);
                    new_start = new_start.min(new_index);
                    new_end = new_end.max(new_index);
                }
                DiffOp::Insert { old_index, new_index, new_len } => {
                    old_start = old_start.min(old_index);
                    old_end = old_end.max(old_index);
                    new_start = new_start.min(new_index);
                    new_end = new_end.max(new_index + new_len);
                }
            }
        }
        out.push_str(&format!(
            "@@ -{} +{} @@\n",
            hunk_range(old_start, old_end - old_start),
            hunk_range(new_start, new_end - new_start)
        ));
        let mut emit = |tag: char, line: &str| {
            out.push(tag);
            out.push_str(line);
            if !line.ends_with('\n') {
                out.push('\n');
                out.push_str("\\ No newline at end of file\n");
            }
        };
        for op in &group {
            match *op {
                DiffOp::Equal { old_index, len, .. } => {
                    for i in 0..len {
                        emit(' ', old_lines[old_index + i]);
                    }
                }
                DiffOp::Delete { old_index, old_len, .. } => {
                    for i in 0..old_len {
                        emit('-', old_lines[old_index + i]);
                    }
                }
                DiffOp::Insert { new_index, new_len, .. } => {
                    for i in 0..new_len {
                        emit('+', new_lines[new_index + i]);
                    }
                }
            }
        }
    }
    out
}
