#[derive(Debug, Clone, PartialEq)]
enum Token {
    Literal(char),
    Any,           // ?
    ZeroOrMore,    // * (does not match `/`)
    RecursivePrefix,  // **/ at start
    RecursiveSuffix,  // /** at end
    RecursiveZeroOrMore, // /**/ in the middle
    Class { negated: bool, ranges: Vec<(char, char)> },
    Alternates(Vec<Vec<Token>>),
}

#[derive(Debug, Clone)]
pub struct Glob {
    tokens: Vec<Token>,
}

