    glob: &'a str,
    chars: std::iter::Peekable<std::str::Chars<'a>>,
    stack: Vec<Vec<Token>>,
    prev: Option<char>,
    cur: Option<char>,
}

impl<'a> Parser<'a> {
    fn error(&self, kind: &str) -> GlobError {
        GlobError { glob: self.glob.to_string(), kind: kind.to_string() }
    }

    fn bump(&mut self) -> Option<char> {
        self.prev = self.cur;
        self.cur = self.chars.next();
        self.cur
    }

    fn peek(&mut self) -> Option<char> {
        self.chars.peek().copied()
    }

    fn push_token(&mut self, tok: Token) -> Result<(), GlobError> {
        if let Some(pat) = self.stack.last_mut() {
            pat.push(tok);
            Ok(())
        } else {
            Err(self.error("unopened alternate group"))
        }
    }

    fn pop_token(&mut self) -> Result<Token, GlobError> {
        if let Some(pat) = self.stack.last_mut() {
            if let Some(t) = pat.pop() {
                return Ok(t);
            }
        }
        Err(self.error("unopened alternate group"))
    }

    fn have_tokens(&self) -> Result<bool, GlobError> {
        match self.stack.last() {
            None => Err(self.error("unopened alternate group")),
            Some(ref pat) => Ok(!pat.is_empty()),
        }
    }

    fn parse_star(&mut self) -> Result<(), GlobError> {
        let prev = self.prev;
        if self.peek() != Some('*') {
            self.push_token(Token::ZeroOrMore)?;
            return Ok(());
        }
        assert!(self.bump() == Some('*'));
        if !self.have_tokens()? {
            if !self.peek().map_or(true, |c| c == '/') {
                self.push_token(Token::ZeroOrMore)?;
                self.push_token(Token::ZeroOrMore)?;
            } else {
                self.push_token(Token::RecursivePrefix)?;
                assert!(self.bump().map_or(true, |c| c == '/'));
            }
            return Ok(());
        }

        if !prev.map(|c| c == '/').unwrap_or(false) {
            if self.stack.len() <= 1 || (prev != Some(',') && prev != Some('{')) {
                self.push_token(Token::ZeroOrMore)?;
                self.push_token(Token::ZeroOrMore)?;
                return Ok(());
            }
        }
        let is_suffix = match self.peek() {
            None => {
                assert!(self.bump().is_none());
                true
            }
            Some(',') | Some('}') if self.stack.len() >= 2 => true,
            Some(c) if c == '/' => {
                assert!(self.bump().map_or(false, |c| c == '/'));
                false
            }
            _ => {
                self.push_token(Token::ZeroOrMore)?;
                self.push_token(Token::ZeroOrMore)?;
                return Ok(());
            }
        };
        match self.pop_token()? {
            Token::RecursivePrefix => {
                self.push_token(Token::RecursivePrefix)?;
            }
            Token::RecursiveSuffix => {
                self.push_token(Token::RecursiveSuffix)?;
            }
            _ => {
                if is_suffix {
                    self.push_token(Token::RecursiveSuffix)?;
                } else {
                    self.push_token(Token::RecursiveZeroOrMore)?;
                }
            }
        }
        Ok(())
    }

    fn parse_class(&mut self) -> Result<(), GlobError> {
        fn add_to_last_range(glob: &str, r: &mut (char, char), add: char) -> Result<(), GlobError> {
            r.1 = add;
            if r.1 < r.0 {
                Err(GlobError { glob: glob.to_string(), kind: "invalid range; '{}' > '{}'".to_string() })
            } else {
                Ok(())
            }
        }
        let mut ranges = vec![];
        let negated = match self.chars.peek() {
            Some(&'!') | Some(&'^') => {
                let bump = self.bump();
                assert!(bump == Some('!') || bump == Some('^'));
                true
            }
            _ => false,
        };
