            let c = match self.bump() {
                Some(c) => c,
                None => return Err(self.error("unclosed character class; missing ']'")),
            };
            match c {
                ']' => {
                    if first {
                        ranges.push((']', ']'));
                    } else {
                        break;
                    }
                }
                '-' => {
                    if first {
                        ranges.push(('-', '-'));
                    } else if in_range {
                        let r = ranges.last_mut().unwrap();
                        add_to_last_range(self.glob, r, '-')?;
                        in_range = false;
                    } else {
                        assert!(!ranges.is_empty());
                        in_range = true;
                    }
                }
                c => {
                    if in_range {
                        let r = ranges.last_mut().unwrap();
                        add_to_last_range(self.glob, r, c)?;
                    } else {
                        ranges.push((c, c));
                    }
                    in_range = false;
                }
            }
            first = false;
        }
        if in_range {
            ranges.push(('-', '-'));
        }
        self.push_token(Token::Class { negated, ranges })
    }

    fn parse(mut self) -> Result<Glob, GlobError> {
        while let Some(c) = self.bump() {
            match c {
                '?' => self.push_token(Token::Any)?,
                '*' => self.parse_star()?,
                '[' => self.parse_class()?,
                '{' => {
                    if self.stack.len() > 1 {
                        return Err(self.error("nested alternate groups are not allowed"));
                    }
                    self.stack.push(Vec::new());
                }
                '}' => {
                    if self.stack.len() == 1 {
                        return Err(self.error("unopened alternate group"));
                    }
                    let mut alts = Vec::new();
                    // collect all alternates pushed since '{'
                    while self.stack.len() > 1 {
                        alts.push(self.stack.pop().unwrap());
                    }
                    alts.reverse();
                    self.push_token(Token::Alternates(alts))?;
                }
                ',' => {
                    if self.stack.len() > 1 {
                        self.stack.push(Vec::new());
                    } else {
                        self.push_token(Token::Literal(','))?;
                    }
                }
                '\\' => match self.bump() {
                    None => return Err(self.error("dangling '\\'")),
                    Some(c) => self.push_token(Token::Literal(c))?,
                },
                c => self.push_token(Token::Literal(c))?,
            }
        }
        if self.stack.len() > 1 {
            return Err(self.error("unclosed alternate group; missing '}' (maybe escape '{' with '[{]'?)"));
        }
        let tokens = self.stack.pop().unwrap();
        Ok(Glob { tokens })
    }
}

impl Glob {
    pub fn new(glob: &str) -> Result<Glob, GlobError> {
        let p = Parser { glob, chars: glob.chars().peekable(), stack: vec![Vec::new()], prev: None, cur: None };
        p.parse()
    }

    pub fn is_match(&self, path: &str) -> bool {
        let chars: Vec<char> = path.chars().collect();
        match_tokens(&self.tokens, 0, &chars, 0)
    }
}

fn class_matches(negated: bool, ranges: &[(char, char)], c: char) -> bool {
    let found = ranges.iter().any(|(a, b)| *a <= c && c <= *b);
    found != negated
}

fn match_tokens(tokens: &[Token], ti: usize, chars: &[char], ci: usize) -> bool {
    if ti == tokens.len() {
        return ci == chars.len();
    }
    match &tokens[ti] {
        Token::Literal(l) => {
            if ci < chars.len() && chars[ci] == *l {
                match_tokens(tokens, ti + 1, chars, ci + 1)
            } else {
                false
            }
        }
        Token::Any => {
            if ci < chars.len() && chars[ci] != '/' {
                match_tokens(tokens, ti + 1, chars, ci + 1)
            } else {
                false
            }
        }
        Token::ZeroOrMore => {
            // match zero or more non-'/' chars
            let mut k = ci;
            loop {
                if match_tokens(tokens, ti + 1, chars, k) {
                    return true;
                }
                if k < chars.len() && chars[k] != '/' {
                    k += 1;
                } else {
                    return false;
                }
            }
        }
        Token::RecursivePrefix => {
            // `**/` at the start: matches any number of leading components
            if match_tokens(tokens, ti + 1, chars, ci) {
                return true;
            }
            let mut k = ci;
            while k < chars.len() {
                if chars[k] == '/' && match_tokens(tokens, ti + 1, chars, k + 1) {
                    return true;
                }
                k += 1;
            }
            false
        }
        Token::RecursiveSuffix => {
            // `/**` at the end: matches `/` followed by anything
            ci < chars.len() && chars[ci] == '/' && ti + 1 == tokens.len()
        }
        Token::RecursiveZeroOrMore => {
            // `/**/` in the middle: matches `/` or `/anything/`
            if ci >= chars.len() || chars[ci] != '/' {
                return false;
            }
            if match_tokens(tokens, ti + 1, chars, ci + 1) {
                return true;
            }
            let mut k = ci + 1;
            while k < chars.len() {
                if chars[k] == '/' && match_tokens(tokens, ti + 1, chars, k + 1) {
                    return true;
                }
                k += 1;
            }
            false
        }
        Token::Class { negated, ranges } => {
            if ci < chars.len() && chars[ci] != '/' && class_matches(*negated, ranges, chars[ci]) {
                match_tokens(tokens, ti + 1, chars, ci + 1)
            } else {
                false
            }
        }
        Token::Alternates(alts) => {
            for alt in alts {
                // build combined token list: alt + rest
                let mut combined: Vec<Token> = alt.clone();
                combined.extend_from_slice(&tokens[ti + 1..]);
                if match_tokens(&combined, 0, chars, ci) {
                    return true;
                }
            }
            false
        }
    }
}

/// A single gitignore-style pattern.
#[derive(Debug, Clone)]
pub struct IgnoreGlob {
    pub original: String,
    pub actual: String,
    pub is_whitelist: bool,
    pub is_only_dir: bool,
    glob: Glob,
}

pub struct Gitignore {
    globs: Vec<IgnoreGlob>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Match {
    None,
    Ignore,
    Whitelist,
}

impl Gitignore {
    pub fn new() -> Self {
        Gitignore { globs: Vec::new() }
    }

    /// Add a single gitignore line.
    pub fn add_line(&mut self, line: &str) -> Result<(), GlobError> {
        let mut line = line;
        if line.starts_with('#') {
            return Ok(());
        }
        if !line.ends_with("\\ ") {
            line = line.trim_end();
        }
        if line.is_empty() {
            return Ok(());
        }
        let original = line.to_string();
        let mut is_whitelist = false;
        let mut is_only_dir = false;
        let mut is_absolute = false;
        if line.starts_with("\\!") || line.starts_with("\\#") {
            line = &line[1..];
            is_absolute = line.starts_with('/');
        } else {
            if line.starts_with('!') {
                is_whitelist = true;
                line = &line[1..];
            }
            if line.starts_with('/') {
                line = &line[1..];
                is_absolute = true;
            }
        }
        if line.ends_with('/') {
            is_only_dir = true;
            line = &line[..line.len() - 1];
            if line.ends_with('\\') {
                line = &line[..line.len() - 1];
            }
        }
        let mut actual = line.to_string();
        if !is_absolute && !line.contains('/') {
            if !actual.starts_with("**/") {
                actual = format!("**/{}", actual);
            }
        }
        if actual.ends_with("/**") {
            actual = format!("{}/*", actual);
        }
        let glob = Glob::new(&actual)?;
        self.globs.push(IgnoreGlob { original, actual, is_whitelist, is_only_dir, glob });
        Ok(())
    }

    pub fn add_str(&mut self, contents: &str) -> Result<(), GlobError> {
        for line in contents.lines() {
            self.add_line(line)?;
        }
        Ok(())
    }

    fn strip<'a>(&self, path: &'a str) -> &'a str {
        let mut p = path;
        if let Some(s) = p.strip_prefix("./") {
            p = s;
        }
        p
    }

    pub fn matched(&self, path: &str, is_dir: bool) -> Match {
        if self.globs.is_empty() {
            return Match::None;
        }
        let path = self.strip(path);
        for glob in self.globs.iter().rev() {
            if glob.glob.is_match(path) {
                if !glob.is_only_dir || is_dir {
                    return if glob.is_whitelist { Match::Whitelist } else { Match::Ignore };
                }
            }
        }
        Match::None
    }
}
