//! A tiny TOML reader, sufficient for `statix.toml`.

use std::collections::BTreeMap;

#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Str(String),
    Int(String),
    Float(String),
    Bool(bool),
    Array(Vec<(Value, usize)>), // value with its start offset
    Table(BTreeMap<String, Value>),
}

#[derive(Debug)]
pub struct TomlError {
    pub message: String,
    pub line: usize,
    pub col: usize,
}

impl std::fmt::Display for TomlError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "{} at line {} column {}", self.message, self.line, self.col)
    }
}

pub struct Document {
    pub text: String,
    /// top level key/values with the offset of the value
    pub values: Vec<(String, Value, usize)>,
}

pub fn line_col(text: &str, offset: usize) -> (usize, usize) {
    let offset = offset.min(text.len());
    let before = &text[..offset];
    let line = before.matches('\n').count() + 1;
    let col = before.rfind('\n').map(|i| offset - i - 1).unwrap_or(offset) + 1;
    (line, col)
}

struct P<'a> {
    text: &'a str,
    bytes: &'a [u8],
    pos: usize,
}

fn describe_token(p: &P) -> String {
    match p.peek() {
        None => "eof".to_string(),
        Some(b'\n') => "a newline".to_string(),
        Some(b'=') => "an equals".to_string(),
        Some(b'[') => "a left bracket".to_string(),
        Some(b']') => "a right bracket".to_string(),
        Some(b'{') => "a left brace".to_string(),
        Some(b'}') => "a right brace".to_string(),
        Some(b',') => "a comma".to_string(),
        Some(b'.') => "a period".to_string(),
        Some(b'"') | Some(b'\'') => "a string".to_string(),
        Some(b'#') => "a comment".to_string(),
        Some(b' ') | Some(b'\t') => "whitespace".to_string(),
        Some(c) if c.is_ascii_alphanumeric() || c == b'_' || c == b'-' => "an identifier".to_string(),
        Some(_) => "an identifier".to_string(),
    }
}

impl<'a> P<'a> {
    fn peek(&self) -> Option<u8> {
        self.bytes.get(self.pos).copied()
    }
    fn err(&self, message: impl Into<String>, at: usize) -> TomlError {
        let (line, col) = line_col(self.text, at);
        TomlError { message: message.into(), line, col }
    }
    fn skip_ws(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\t' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }
    fn skip_comment(&mut self) {
        if self.peek() == Some(b'#') {
            while let Some(c) = self.peek() {
                if c == b'\n' {
                    break;
                }
                self.pos += 1;
            }
        }
    }
    fn skip_ws_comments_newlines(&mut self) {
        loop {
            self.skip_ws();
            self.skip_comment();
            match self.peek() {
                Some(b'\n') => self.pos += 1,
                Some(b'\r') => self.pos += 1,
                _ => break,
            }
        }
    }
    fn expect_newline_or_eof(&mut self) -> Result<(), TomlError> {
        self.skip_ws();
        self.skip_comment();
        match self.peek() {
            None => Ok(()),
            Some(b'\n') => {
                self.pos += 1;
                Ok(())
            }
            Some(b'\r') => {
                self.pos += 1;
                if self.peek() == Some(b'\n') {
                    self.pos += 1;
                }
                Ok(())
            }
            Some(_) => Err(self.err(format!("expected newline, found {}", describe_token(self)), self.pos)),
        }
    }
    fn parse_key(&mut self) -> Result<String, TomlError> {
        match self.peek() {
            Some(b'"') => {
                let (s, _) = self.parse_basic_string()?;
                Ok(s)
            }
            Some(b'\'') => {
                let (s, _) = self.parse_literal_string()?;
                Ok(s)
            }
            Some(c) if c.is_ascii_alphanumeric() || c == b'_' || c == b'-' => {
                let start = self.pos;
                while let Some(c) = self.peek() {
                    if c.is_ascii_alphanumeric() || c == b'_' || c == b'-' {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                Ok(self.text[start..self.pos].to_string())
            }
            _ => Err(self.err(format!("expected a table key, found {}", describe_token(self)), self.pos)),
        }
    }
    fn parse_basic_string(&mut self) -> Result<(String, usize), TomlError> {
        let start = self.pos;
        self.pos += 1; // opening quote
        let mut out = String::new();
        loop {
            match self.peek() {
                None => return Err(self.err("unterminated string", start)),
                Some(b'"') => {
                    self.pos += 1;
                    return Ok((out, start));
                }
                Some(b'\n') => return Err(self.err("newline in string found", self.pos)),
                Some(b'\\') => {
                    self.pos += 1;
                    match self.peek() {
                        Some(b'n') => out.push('\n'),
                        Some(b't') => out.push('\t'),
                        Some(b'r') => out.push('\r'),
                        Some(b'\\') => out.push('\\'),
                        Some(b'"') => out.push('"'),
                        Some(b'b') => out.push('\u{8}'),
                        Some(b'f') => out.push('\u{c}'),
                        Some(b'u') | Some(b'U') => {
                            let n = if self.peek() == Some(b'u') { 4 } else { 8 };
                            let hex_start = self.pos + 1;
                            let hex_end = (hex_start + n).min(self.bytes.len());
                            let hex = &self.text[hex_start..hex_end];
                            match u32::from_str_radix(hex, 16).ok().and_then(char::from_u32) {
                                Some(c) => {
                                    out.push(c);
                                    self.pos = hex_end - 1;
                                }
                                None => return Err(self.err("invalid unicode escape", self.pos)),
                            }
                        }
                        _ => return Err(self.err("invalid escape character in string", self.pos)),
                    }
                    self.pos += 1;
                }
                Some(_) => {
                    let c = self.text[self.pos..].chars().next().unwrap();
                    out.push(c);
                    self.pos += c.len_utf8();
                }
            }
        }
    }
    fn parse_literal_string(&mut self) -> Result<(String, usize), TomlError> {
        let start = self.pos;
        self.pos += 1;
        let mut out = String::new();
        loop {
            match self.peek() {
                None => return Err(self.err("unterminated string", start)),
                Some(b'\'') => {
                    self.pos += 1;
                    return Ok((out, start));
                }
                Some(b'\n') => return Err(self.err("newline in string found", self.pos)),
                Some(_) => {
                    let c = self.text[self.pos..].chars().next().unwrap();
                    out.push(c);
                    self.pos += c.len_utf8();
                }
            }
        }
    }
    fn parse_value(&mut self) -> Result<(Value, usize), TomlError> {
        let start = self.pos;
        match self.peek() {
            None | Some(b'\n') | Some(b'\r') | Some(b'=') | Some(b']') | Some(b'}') | Some(b',') | Some(b'#') => {
                Err(self.err(format!("expected a value, found {}", describe_token(self)), self.pos))
            }
            Some(b'"') => {
                // multi-line basic strings are not supported beyond the basics
                if self.text[self.pos..].starts_with("\"\"\"") {
                    let end = self.text[self.pos + 3..].find("\"\"\"").map(|i| i + self.pos + 3);
                    match end {
                        Some(e) => {
                            let s = self.text[self.pos + 3..e].to_string();
                            self.pos = e + 3;
                            Ok((Value::Str(s), start))
                        }
                        None => Err(self.err("unterminated string", start)),
                    }
                } else {
                    let (s, _) = self.parse_basic_string()?;
                    Ok((Value::Str(s), start))
                }
            }
            Some(b'\'') => {
                if self.text[self.pos..].starts_with("'''") {
                    let end = self.text[self.pos + 3..].find("'''").map(|i| i + self.pos + 3);
                    match end {
                        Some(e) => {
                            let s = self.text[self.pos + 3..e].to_string();
                            self.pos = e + 3;
                            Ok((Value::Str(s), start))
                        }
                        None => Err(self.err("unterminated string", start)),
                    }
                } else {
                    let (s, _) = self.parse_literal_string()?;
                    Ok((Value::Str(s), start))
                }
            }
            Some(b'[') => {
                self.pos += 1;
                let mut items = Vec::new();
                loop {
                    self.skip_ws_comments_newlines();
                    match self.peek() {
                        Some(b']') => {
                            self.pos += 1;
                            break;
                        }
                        None => {
                            return Err(self.err(
                                format!("expected a right bracket, found {}", describe_token(self)),
                                self.pos,
                            ))
                        }
                        _ => {}
                    }
                    let (v, off) = self.parse_value()?;
                    items.push((v, off));
                    self.skip_ws_comments_newlines();
                    match self.peek() {
                        Some(b',') => {
                            self.pos += 1;
                        }
                        Some(b']') => {
                            self.pos += 1;
                            break;
                        }
                        _ => {
                            return Err(self.err(
                                format!("expected a right bracket, found {}", describe_token(self)),
                                self.pos,
                            ))
                        }
                    }
                }
                Ok((Value::Array(items), start))
            }
            Some(b'{') => {
                self.pos += 1;
                let mut table = BTreeMap::new();
                self.skip_ws();
                if self.peek() == Some(b'}') {
                    self.pos += 1;
                    return Ok((Value::Table(table), start));
                }
                loop {
                    self.skip_ws();
                    let key = self.parse_key()?;
                    self.skip_ws();
                    if self.peek() != Some(b'=') {
                        return Err(self.err(format!("expected an equals, found {}", describe_token(self)), self.pos));
                    }
                    self.pos += 1;
                    self.skip_ws();
                    let (v, _) = self.parse_value()?;
                    table.insert(key, v);
                    self.skip_ws();
                    match self.peek() {
                        Some(b',') => self.pos += 1,
                        Some(b'}') => {
                            self.pos += 1;
                            break;
                        }
                        _ => {
                            return Err(self.err(format!("expected a right brace, found {}", describe_token(self)), self.pos))
                        }
                    }
                }
                Ok((Value::Table(table), start))
            }
            Some(c) if c == b't' && self.text[self.pos..].starts_with("true") => {
                self.pos += 4;
                Ok((Value::Bool(true), start))
            }
            Some(c) if c == b'f' && self.text[self.pos..].starts_with("false") => {
                self.pos += 5;
                Ok((Value::Bool(false), start))
            }
            Some(c) if c.is_ascii_digit() || c == b'-' || c == b'+' => {
                while let Some(c) = self.peek() {
                    if c.is_ascii_alphanumeric() || c == b'_' || c == b'-' || c == b'+' || c == b'.' || c == b':' {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                let s = &self.text[start..self.pos];
                if s.contains('.') || s.contains('e') || s.contains('E') {
                    Ok((Value::Float(s.to_string()), start))
                } else {
                    Ok((Value::Int(s.to_string()), start))
                }
            }
            Some(_) => Err(self.err(format!("expected a value, found {}", describe_token(self)), self.pos)),
        }
    }
}

pub fn parse(text: &str) -> Result<Document, TomlError> {
    let mut p = P { text, bytes: text.as_bytes(), pos: 0 };
    let mut values: Vec<(String, Value, usize)> = Vec::new();
    let mut in_table = false;
    loop {
        p.skip_ws_comments_newlines();
        match p.peek() {
            None => break,
            Some(b'[') => {
                // table header; skip to end of line
                in_table = true;
                while let Some(c) = p.peek() {
                    if c == b'\n' {
                        break;
                    }
                    p.pos += 1;
                }
                continue;
            }
            _ => {}
        }
        let key_start = p.pos;
        let key = p.parse_key()?;
        p.skip_ws();
        // dotted keys: a.b = ...
        let mut full_key = key.clone();
        while p.peek() == Some(b'.') {
            p.pos += 1;
            p.skip_ws();
            let k = p.parse_key()?;
            full_key = format!("{}.{}", full_key, k);
            p.skip_ws();
        }
        if p.peek() != Some(b'=') {
            return Err(p.err(format!("expected an equals, found {}", describe_token(&p)), p.pos));
        }
        p.pos += 1;
        p.skip_ws();
        if p.peek().is_none() {
            return Err(p.err("unexpected eof encountered", p.pos));
        }
        let (value, off) = match p.parse_value() {
            Ok(v) => v,
            Err(e) => {
                // special case: eof inside arrays
                return Err(e);
            }
        };
        p.expect_newline_or_eof()?;
        if !in_table && !full_key.contains('.') {
            if values.iter().any(|(k, _, _)| *k == full_key) {
                return Err(p.err(format!("duplicate field `{}`", full_key), key_start));
            }
            values.push((full_key, value, off));
        }
    }
    Ok(Document { text: text.to_string(), values })
}
