//! Configuration: config file handling, lint selection, file discovery.

use crate::glob::{Gitignore, Match};
use crate::lints::{self, LintInfo};
use crate::toml::{self, Value};
use std::path::{Path, PathBuf};

#[derive(Debug)]
pub enum ConfigErr {
    InvalidPath(PathBuf),
    Io(std::io::Error),
    ConfFileParse(String),
    InvalidGlob(String),
}

impl std::fmt::Display for ConfigErr {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            ConfigErr::InvalidPath(p) => write!(f, "path error: file not found: {}", p.display()),
            ConfigErr::Io(e) => write!(f, "path error: {}", e),
            ConfigErr::ConfFileParse(e) => write!(f, "unable to parse config file: {}", e),
            ConfigErr::InvalidGlob(e) => write!(f, "error parsing ignore list `{}`", e),
        }
    }
}

#[derive(Debug, Default, Clone)]
pub struct ConfFile {
    pub disabled: Vec<String>,
    pub ignore: Vec<String>,
}

fn type_name(v: &Value) -> String {
    match v {
        Value::Str(s) => format!("string {:?}", s),
        Value::Int(s) => format!("integer `{}`", s),
        Value::Float(s) => format!("floating point `{}`", s),
        Value::Bool(b) => format!("boolean `{}`", b),
        Value::Array(_) => "sequence".to_string(),
        Value::Table(_) => "map".to_string(),
    }
}

fn error_position(text: &str, v: &Value, offset: usize) -> (usize, usize) {
    match v {
        Value::Int(s) | Value::Float(s) => toml::line_col(text, offset + s.len().saturating_sub(1)),
        Value::Array(_) => (1, 1),
        _ => toml::line_col(text, offset),
    }
}

fn string_list(doc: &toml::Document, key: &str) -> Result<Vec<String>, ConfigErr> {
    for (k, v, off) in &doc.values {
        if k == key {
            match v {
                Value::Array(items) => {
                    let mut out = Vec::new();
                    for (item, ioff) in items {
                        match item {
                            Value::Str(s) => out.push(s.clone()),
                            other => {
                                let (line, col) = error_position(&doc.text, other, *ioff);
                                return Err(ConfigErr::ConfFileParse(format!(
                                    "invalid type: {}, expected a string for key `{}` at line {} column {}",
                                    type_name(other),
                                    key,
                                    line,
                                    col
                                )));
                            }
                        }
                    }
                    return Ok(out);
                }
                other => {
                    let (line, col) = error_position(&doc.text, other, *off);
                    return Err(ConfigErr::ConfFileParse(format!(
                        "invalid type: {}, expected a sequence for key `{}` at line {} column {}",
                        type_name(other),
                        key,
                        line,
                        col
                    )));
                }
            }
        }
    }
    Ok(Vec::new())
}

impl ConfFile {
    pub fn from_str(text: &str) -> Result<Self, ConfigErr> {
        let doc = toml::parse(text).map_err(|e| ConfigErr::ConfFileParse(e.to_string()))?;
        let disabled = string_list(&doc, "disabled")?;
        let ignore = string_list(&doc, "ignore")?;
        Ok(ConfFile { disabled, ignore })
    }

    /// Discover the config file at the given path (file or directory).
    pub fn discover(path: &Path) -> Result<Self, ConfigErr> {
        let path = if path.is_dir() {
            let candidate = path.join("statix.toml");
            if !candidate.exists() {
                return Ok(ConfFile::default());
            }
            candidate
        } else {
            path.to_path_buf()
        };
        let text = std::fs::read_to_string(&path).map_err(ConfigErr::Io)?;
        ConfFile::from_str(&text)
    }

    pub fn dump() -> String {
        "disabled = []\nignore = ['.direnv']\n".to_string()
    }
}

/// Validate that a config path exists.
pub fn check_conf_path(path: &Path) -> Result<(), ConfigErr> {
    std::fs::metadata(path).map(|_| ()).map_err(ConfigErr::Io)
}

/// Enabled lints given a list of disabled lint names.
pub fn enabled_lints(disabled: &[String]) -> Vec<&'static LintInfo> {
    lints::LINTS.iter().filter(|l| !disabled.iter().any(|d| d == l.name)).collect()
}

pub fn build_ignore_set(
    ignore: &[String],
    target: &Path,
    unrestricted: bool,
) -> Result<Gitignore, ConfigErr> {
    let mut gitignore = Gitignore::new();
    let gitignore_path = target.join(".gitignore");
    if !unrestricted && gitignore_path.exists() {
        if let Ok(contents) = std::fs::read_to_string(&gitignore_path) {
            gitignore.add_str(&contents).map_err(|e| ConfigErr::InvalidGlob(e.to_string()))?;
        }
    }
    for pattern in ignore {
        gitignore.add_line(pattern).map_err(|e| ConfigErr::InvalidGlob(e.to_string()))?;
    }
    Ok(gitignore)
}

/// Walk a target (file or directory), yielding `.nix` files.
pub fn walk_nix_files(target: &Path, ignore: &Gitignore) -> Result<Vec<PathBuf>, ConfigErr> {
    if !target.exists() {
        return Err(ConfigErr::InvalidPath(target.to_path_buf()));
    }
    let mut files = Vec::new();
    if target.is_dir() {
        walk_dir(target, ignore, &mut files);
    } else if target.extension().map_or(false, |e| e == "nix") {
        files.push(target.to_path_buf());
    }
    Ok(files)
}

fn path_str(p: &Path) -> String {
    p.to_string_lossy().into_owned()
}

fn walk_dir(dir: &Path, ignore: &Gitignore, files: &mut Vec<PathBuf>) {
    let mut entries: Vec<PathBuf> = match std::fs::read_dir(dir) {
        Ok(rd) => rd.filter_map(|e| e.ok()).map(|e| e.path()).collect(),
        Err(_) => return,
    };
    entries.sort();
    for path in entries {
        let is_dir = path.is_dir();
        if ignore.matched(&path_str(&path), is_dir) == Match::Ignore {
            continue;
        }
        if is_dir {
            walk_dir(&path, ignore, files);
        } else if path.is_file() && path.extension().map_or(false, |e| e == "nix") {
            files.push(path);
        }
    }
}
