    let mut out = String::new();
    for (i, piece) in msg.split('`').enumerate() {
        if piece.is_empty() {
            continue;
        }
        if i % 2 == 1 {
            out.push_str(&crate::render::paint(piece, Some(crate::render::Color::Cyan)));
        } else {
