//! Applying fixes.

use crate::analyze::lint_reports;
use crate::lints::{LintInfo, Report};
use crate::parser::parse;
use crate::syntax::TextRange;
use std::collections::VecDeque;

fn total_suggestion_range(report: &Report) -> Option<TextRange> {
    let mut range: Option<TextRange> = None;
    for d in &report.diagnostics {
        if let Some(s) = &d.suggestion {
            range = Some(match range {
                None => s.at,
                Some(r) => TextRange::new(r.start.min(s.at.start), r.end.max(s.at.end)),
            });
        }
    }
    range
}

fn total_diagnostic_range(report: &Report) -> Option<TextRange> {
    let mut range: Option<TextRange> = None;
    for d in &report.diagnostics {
        range = Some(match range {
            None => d.at,
            Some(r) => TextRange::new(r.start.min(d.at.start), r.end.max(d.at.end)),
        });
    }
    range
}

/// Collect fixable reports. Returns None when the source has syntax errors.
fn collect_fixes(src: &str, lints: &[&LintInfo]) -> Option<Vec<Report>> {
    let parsed = parse(src);
    if !parsed.errors.is_empty() {
        return None;
    }
    Some(
        lint_reports(&parsed, lints)
            .into_iter()
            .filter(|r| total_suggestion_range(r).is_some())
            .collect(),
    )
}

fn reorder(mut reports: Vec<Report>) -> Vec<Report> {
    reports.sort_by_key(|r| total_suggestion_range(r).map(|r| r.end).unwrap_or(0));
    let deque = reports.into_iter().fold(VecDeque::new(), |mut deque: VecDeque<Report>, new_elem| {
        let new_range = total_suggestion_range(&new_elem).unwrap();
        match deque.front().map(total_suggestion_range) {
            Some(Some(front_range)) => {
                if new_range.start > front_range.end {
                    deque.push_front(new_elem);
                }
            }
            _ => deque.push_front(new_elem),
        }
        deque
    });
    deque.into()
}

fn apply(src: &str, reports: &[Report]) -> String {
    let mut out = src.to_string();
    for report in reports {
        // suggestions in a report are applied from the end
        let mut suggestions: Vec<_> = report.diagnostics.iter().filter_map(|d| d.suggestion.as_ref()).collect();
        suggestions.sort_by_key(|s| std::cmp::Reverse(s.at.start));
        for s in suggestions {
            if s.at.end <= out.len() {
                out.replace_range(s.at.start..s.at.end, &s.fix);
            }
        }
    }
    out
}

/// Fix everything that can be fixed, in multiple passes.
pub fn fix_all(src: &str, lints: &[&LintInfo]) -> Option<String> {
    let mut current = src.to_string();
    let mut passes = 0;
    loop {
        let reports = collect_fixes(&current, lints)?;
        if reports.is_empty() {
            break;
        }
        let reports = reorder(reports);
        let next = apply(&current, &reports);
        if next == current {
            break;
        }
        current = next;
        passes += 1;
        if passes > 100 {
            break;
        }
    }
    Some(current)
}

#[derive(Debug)]
pub enum SingleFixErr {
    OutOfBounds(usize, usize),
    NoOp,
}

impl std::fmt::Display for SingleFixErr {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            SingleFixErr::OutOfBounds(line, col) => {
                write!(f, "position out of bounds: line {}, col {}", line, col)
            }
            SingleFixErr::NoOp => write!(f, "nothing to fix"),
        }
    }
}

fn pos_to_byte(line: usize, col: usize, src: &str) -> Result<usize, SingleFixErr> {
    let mut offset = 0;
    let target_line = line.saturating_sub(1);
    for (i, l) in src.split_inclusive('\n').enumerate() {
        if i == target_line {
            if col < l.len() {
                return Ok(offset + col);
            } else {
                return Err(SingleFixErr::OutOfBounds(line, col));
            }
        }
        offset += l.len();
    }
    Err(SingleFixErr::OutOfBounds(line, col))
}

/// Fix exactly one issue at the given position.
pub fn fix_single(line: usize, col: usize, src: &str, lints: &[&LintInfo]) -> Result<String, SingleFixErr> {
    let offset = pos_to_byte(line, col, src)?;
    let reports = collect_fixes(src, lints).unwrap_or_default();
    let report = reports
        .into_iter()
        .find(|r| total_diagnostic_range(r).map_or(false, |range| range.contains(offset)))
        .ok_or(SingleFixErr::NoOp)?;
    Ok(apply(src, &[report]))
}
