    }
    Some(current)
}

#[derive(Debug)]
pub enum SingleFixErr {
    OutOfBounds(usize, usize),
    NoOp,
}

impl std::fmt::Display for SingleFixErr {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            SingleFixErr::OutOfBounds(line, col) => {
                write!(f, "position out of bounds: line {}, col {}", line, col)
            }
            SingleFixErr::NoOp => write!(f, "nothing to fix"),
        }
    }
}

fn pos_to_byte(line: usize, col: usize, src: &str) -> Result<usize, SingleFixErr> {
    let mut offset = 0;
    let target_line = line.saturating_sub(1);
    for (i, l) in src.split_inclusive('\n').enumerate() {
        if i == target_line {
            if col < l.len() {
                return Ok(offset + col);
            } else {
                return Err(SingleFixErr::OutOfBounds(line, col));
            }
        }
        offset += l.len();
    }
    Err(SingleFixErr::OutOfBounds(line, col))
}

/// Fix exactly one issue at the given position.
pub fn fix_single(line: usize, col: usize, src: &str, lints: &[&LintInfo]) -> Result<String, SingleFixErr> {
    let offset = pos_to_byte(line, col, src)?;
    let reports = collect_fixes(src, lints).unwrap_or_default();
    let report = reports
        .into_iter()
        .find(|r| total_diagnostic_range(r).map_or(false, |range| range.contains(offset)))
        .ok_or(SingleFixErr::NoOp)?;
    Ok(apply(src, &[report]))
}
