fn exit_with_error(msg: &str, usage: Option<&str>) -> ! {
    let mut out = format!("error: {}\n\n", msg);
    if let Some(u) = usage {
        out.push_str(&format!("USAGE:\n    {}\n\n", u));
    }
    out.push_str("For more information try --help\n");
    eprint!("{}", out);
    process::exit(2);
}

fn unexpected_argument(arg: &str, usage: &str) -> ! {
    let mut msg = format!(
        "Found argument '{}' which wasn't expected, or isn't valid in this context",
        arg
    );
    if arg.starts_with('-') {
        msg.push_str(&format!(
            "\n\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`",
            arg, arg
        ));
    }
    exit_with_error(&msg, Some(usage));
}

/// Description of an option/flag accepted by a subcommand.
struct OptSpec {
    short: char,
    long: &'static str,
    /// value name if the option takes a value
    value: Option<&'static str>,
    multiple: bool,
}

impl OptSpec {
    fn display(&self) -> String {
        match self.value {
            Some(v) => {
                if self.multiple {
                    format!("--{} <{}>...", self.long, v)
                } else {
                    format!("--{} <{}>", self.long, v)
                }
            }
            None => format!("--{}", self.long),
        }
    }
}

const CHECK_OPTS: &[OptSpec] = &[
    OptSpec { short: 'c', long: "config", value: Some("CONF_PATH"), multiple: false },
    OptSpec { short: 'i', long: "ignore", value: Some("IGNORE"), multiple: true },
    OptSpec { short: 'o', long: "format", value: Some("FORMAT"), multiple: false },
    OptSpec { short: 's', long: "stdin", value: None, multiple: false },
    OptSpec { short: 'u', long: "unrestricted", value: None, multiple: false },
];

const FIX_OPTS: &[OptSpec] = &[
    OptSpec { short: 'c', long: "config", value: Some("CONF_PATH"), multiple: false },
    OptSpec { short: 'd', long: "dry-run", value: None, multiple: false },
    OptSpec { short: 'i', long: "ignore", value: Some("IGNORE"), multiple: true },
    OptSpec { short: 's', long: "stdin", value: None, multiple: false },
    OptSpec { short: 'u', long: "unrestricted", value: None, multiple: false },
];

const SINGLE_OPTS: &[OptSpec] = &[
    OptSpec { short: 'c', long: "config", value: Some("CONF_PATH"), multiple: false },
    OptSpec { short: 'd', long: "dry-run", value: None, multiple: false },
    OptSpec { short: 'p', long: "position", value: Some("POSITION"), multiple: false },
    OptSpec { short: 's', long: "stdin", value: None, multiple: false },
];

/// A parsed occurrence of an option.
struct Occurrence {
    long: &'static str,
    values: Vec<String>,
}

struct Parsed {
    /// occurrences in order of appearance
    occurrences: Vec<Occurrence>,
    positionals: Vec<String>,
    /// flags in order of appearance (long names), deduplicated
    flag_order: Vec<&'static str>,
}

impl Parsed {
    fn count(&self, long: &str) -> usize {
        self.occurrences.iter().filter(|o| o.long == long).count()
    }
    fn values(&self, long: &str) -> Vec<String> {
        self.occurrences.iter().filter(|o| o.long == long).flat_map(|o| o.values.clone()).collect()
    }
    fn first_value(&self, long: &str) -> Option<String> {
        self.occurrences.iter().find(|o| o.long == long).and_then(|o| o.values.first().cloned())
    }
    fn present(&self, long: &str) -> bool {
        self.count(long) > 0
    }
}

fn find_short(opts: &'static [OptSpec], c: char) -> Option<&'static OptSpec> {
    opts.iter().find(|o| o.short == c)
}

fn find_long(opts: &'static [OptSpec], name: &str) -> Option<&'static OptSpec> {
    opts.iter().find(|o| o.long == name)
}

fn is_flag_like(s: &str) -> bool {
    s.starts_with('-') && s.len() > 1
}

/// Generic argument parser for a subcommand.
fn parse_sub(
    bin: &str,
    sub: &str,
    opts: &'static [OptSpec],
    args: &[String],
    max_positionals: usize,
) -> Parsed {
    let usage = sub_usage(bin, sub);
    let help = sub_help(bin, sub);
    let mut parsed = Parsed { occurrences: Vec::new(), positionals: Vec::new(), flag_order: Vec::new() };
    let mut i = 0;
    let mut only_positionals = false;

    let mut record = |parsed: &mut Parsed, spec: &'static OptSpec, values: Vec<String>| {
        if !parsed.flag_order.contains(&spec.long) {
            parsed.flag_order.push(spec.long);
        }
        parsed.occurrences.push(Occurrence { long: spec.long, values });
    };

    while i < args.len() {
        let arg = &args[i];
        if only_positionals || !is_flag_like(arg) {
            if parsed.positionals.len() >= max_positionals {
                unexpected_argument(arg, &usage);
            }
            parsed.positionals.push(arg.clone());
            i += 1;
            continue;
        }
        if arg == "--" {
            only_positionals = true;
            i += 1;
            continue;
        }
        if let Some(long) = arg.strip_prefix("--") {
            let (name, inline_value) = match long.find('=') {
                Some(idx) => (&long[..idx], Some(long[idx + 1..].to_string())),
                None => (long, None),
            };
            if name == "help" {
                print!("{}", help);
                process::exit(0);
            }
            let spec = match find_long(opts, name) {
                Some(s) => s,
                None => unexpected_argument(arg, &usage),
            };
            match spec.value {
                None => {
                    if let Some(v) = inline_value {
                        let msg = format!(
                            "The value '={}' was provided to '--{}' but it wasn't expecting any more values",
                            v, spec.long
                        );
                        eprint!(
                            "error: {}\n\n{}\n\nFor more information try --help\n",
                            msg, usage
                        );
                        process::exit(2);
                    }
                    record(&mut parsed, spec, vec![]);
                    i += 1;
                }
                Some(_) => {
                    let mut values = Vec::new();
                    if let Some(v) = inline_value {
                        values.push(v);
                        i += 1;
                    } else {
                        i += 1;
                        if i >= args.len() || is_flag_like(&args[i]) {
                            exit_with_error(
                                &format!(
                                    "The argument '{}' requires a value but none was supplied",
                                    spec.display()
                                ),
                                Some(&usage),
                            );
                        }
                        values.push(args[i].clone());
                        i += 1;
                        if spec.multiple {
                            while i < args.len() && !is_flag_like(&args[i]) && args[i] != "--" {
                                values.push(args[i].clone());
                                i += 1;
                            }
                        }
                    }
                    record(&mut parsed, spec, values);
                }
            }
            continue;
        }
        // short flag cluster
        let chars: Vec<char> = arg[1..].chars().collect();
        let mut j = 0;
        while j < chars.len() {
            let c = chars[j];
            if c == 'h' {
                print!("{}", help);
                process::exit(0);
            }
            let spec = match find_short(opts, c) {
                Some(s) => s,
                None => unexpected_argument(&format!("-{}", c), &usage),
            };
            match spec.value {
                None => {
                    record(&mut parsed, spec, vec![]);
                    j += 1;
                }
                Some(_) => {
                    let rest: String = chars[j + 1..].iter().collect();
                    let mut values = Vec::new();
                    if !rest.is_empty() {
                        let v = rest.strip_prefix('=').unwrap_or(&rest).to_string();
                        values.push(v);
                        i += 1;
                    } else {
                        i += 1;
                        if i >= args.len() || is_flag_like(&args[i]) {
                            exit_with_error(
                                &format!(
                                    "The argument '{}' requires a value but none was supplied",
                                    spec.display()
                                ),
                                Some(&usage),
                            );
                        }
                        values.push(args[i].clone());
                        i += 1;
                        if spec.multiple {
                            while i < args.len() && !is_flag_like(&args[i]) && args[i] != "--" {
                                values.push(args[i].clone());
                                i += 1;
                            }
                        }
                    }
                    record(&mut parsed, spec, values);
                    j = chars.len() + 1; // consumed the rest
                }
            }
        }
        if j == chars.len() {
            i += 1;
        }
    }
    parsed
}

fn check_duplicates(parsed: &Parsed, opts: &'static [OptSpec], usage: &str, validate: &dyn Fn(&str, &str)) {
    // per-argument validation in order of first appearance
    for long in &parsed.flag_order {
        let spec = find_long(opts, long).unwrap();
        if let Some(v) = parsed.first_value(long) {
            validate(long, &v);
        }
        if parsed.count(long) > 1 {
            exit_with_error(
                &format!(
                    "The argument '{}' was provided more than once, but cannot be used multiple times",
                    spec.display()
                ),
                Some(usage),
            );
        }
    }
}

fn parse_format(v: &str) -> Result<OutFormat, String> {
    match v {
        "stderr" => Ok(OutFormat::Stderr),
        "errfmt" => Ok(OutFormat::Errfmt),
        "json" => Err("statix was not compiled with the `json` feature flag".to_string()),
        _ => Err("unknown output format, try: json, errfmt".to_string()),
    }
}

fn parse_position(v: &str) -> Result<(usize, usize), String> {
    let err = || format!("unable to parse `{}` as line and column", v);
    let (l, c) = v.split_once(',').ok_or_else(err)?;
    let line = l.parse::<usize>().map_err(|_| err())?;
    let col = c.parse::<usize>().map_err(|_| err())?;
    Ok((line, col))
}

pub fn parse_warning_code(v: &str) -> Result<u32, String> {
    let mut chars = v.chars();
    let err = || format!("unable to parse `{}` as warning code", v);
    let first = chars.next().ok_or_else(err)?;
    match first.to_ascii_lowercase() {
        'w' => chars.as_str().parse::<u32>().map_err(|_| err()),
        _ => Ok(0),
    }
}

fn invalid_value(arg: &str, msg: &str) -> ! {
    exit_with_error(&format!("Invalid value for '{}': {}", arg, msg), None);
}

pub fn parse_args() -> Command {
    let argv: Vec<String> = std::env::args().collect();
    let bin = std::path::Path::new(&argv[0])
        .file_name()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_else(|| "statix".to_string());
    let args = &argv[1..];

    if args.is_empty() {
        eprint!("{}", main_help(&bin));
        process::exit(2);
    }

    let first = &args[0];
    match first.as_str() {
        "-h" | "--help" | "help" if first != "help" => {
            print!("{}", main_help(&bin));
            process::exit(0);
        }
        "-V" | "--version" => {
            println!("statix {}", VERSION);
            process::exit(0);
        }
        _ => {}
    }

    match first.as_str() {
        "help" => {
            if args.len() == 1 {
                print!("{}", main_help(&bin));
                process::exit(0);
            }
            let sub = &args[1];
            match sub.as_str() {
                "check" | "fix" | "single" | "explain" | "list" | "dump" => {
                    print!("{}", sub_help(&bin, sub));
                    process::exit(0);
                }
                "help" => {
                    print!("{}", main_help(&bin));
                    process::exit(0);
                }
                _ => {
                    eprint!(
                        "error:  The subcommand '{}' wasn't recognized\n\nUSAGE:\n    {} <subcommands>\n\nFor more information try --help\n",
                        sub, bin
                    );
                    process::exit(2);
                }
            }
        }
        "check" => {
            let usage = sub_usage(&bin, "check");
            let parsed = parse_sub(&bin, "check", CHECK_OPTS, &args[1..], 1);
            check_duplicates(&parsed, CHECK_OPTS, &usage, &|long, v| {
                if long == "format" {
                    if let Err(e) = parse_format(v) {
                        invalid_value("--format <FORMAT>", &e);
                    }
                }
            });
            let format = parsed.first_value("format").map(|v| parse_format(&v).unwrap()).unwrap_or(OutFormat::Stderr);
            Command::Check(CheckArgs {
                target: parsed.positionals.first().cloned().unwrap_or_else(|| ".".to_string()),
                conf_path: parsed.first_value("config").unwrap_or_else(|| ".".to_string()),
                ignore: parsed.values("ignore"),
                format,
                stdin: parsed.present("stdin"),
                unrestricted: parsed.present("unrestricted"),
            })
        }
        "fix" => {
            let usage = sub_usage(&bin, "fix");
            let parsed = parse_sub(&bin, "fix", FIX_OPTS, &args[1..], 1);
            check_duplicates(&parsed, FIX_OPTS, &usage, &|_, _| {});
            Command::Fix(FixArgs {
                target: parsed.positionals.first().cloned().unwrap_or_else(|| ".".to_string()),
                conf_path: parsed.first_value("config").unwrap_or_else(|| ".".to_string()),
                ignore: parsed.values("ignore"),
                dry_run: parsed.present("dry-run"),
                stdin: parsed.present("stdin"),
                unrestricted: parsed.present("unrestricted"),
            })
        }
        "single" => {
            let usage = sub_usage(&bin, "single");
            let parsed = parse_sub(&bin, "single", SINGLE_OPTS, &args[1..], 1);
            if !parsed.present("position") {
                // smart usage: required args, then used flags, then positional
                let mut usage_parts = vec![format!("{} single", bin)];
                let has_flags = !parsed.flag_order.is_empty();
                let has_pos = !parsed.positionals.is_empty();
                if !has_flags && !has_pos {
                    usage_parts.push("[OPTIONS]".to_string());
                }
                usage_parts.push("--position <POSITION>".to_string());
                for long in &parsed.flag_order {
                    let spec = find_long(SINGLE_OPTS, long).unwrap();
                    if spec.value.is_none() {
                        usage_parts.push(format!("--{}", spec.long));
                    }
                }
                if has_pos {
                    usage_parts.push("<TARGET>".to_string());
                } else if !has_flags {
                    usage_parts.push("[TARGET]".to_string());
                }
                exit_with_error(
                    "The following required arguments were not provided:\n    --position <POSITION>",
                    Some(&usage_parts.join(" ")),
                );
            }
            check_duplicates(&parsed, SINGLE_OPTS, &usage, &|long, v| {
                if long == "position" {
                    if let Err(e) = parse_position(v) {
                        invalid_value("--position <POSITION>", &e);
                    }
                }
            });
            let position = parse_position(&parsed.first_value("position").unwrap()).unwrap();
            Command::Single(SingleArgs {
                target: parsed.positionals.first().cloned(),
                conf_path: parsed.first_value("config").unwrap_or_else(|| ".".to_string()),
                dry_run: parsed.present("dry-run"),
                position,
                stdin: parsed.present("stdin"),
            })
        }
        "explain" => {
            let usage = sub_usage(&bin, "explain");
            let parsed = parse_sub(&bin, "explain", &[], &args[1..], 1);
            let target = match parsed.positionals.first() {
                Some(t) => t.clone(),
                None => exit_with_error(
                    "The following required arguments were not provided:\n    <TARGET>",
                    Some(&usage),
                ),
            };
            match parse_warning_code(&target) {
                Ok(code) => Command::Explain(code),
                Err(e) => invalid_value("<TARGET>", &e),
            }
        }
        "list" => {
            parse_sub(&bin, "list", &[], &args[1..], 0);
            Command::List
        }
        "dump" => {
            parse_sub(&bin, "dump", &[], &args[1..], 0);
            Command::Dump
        }
        other => {
            if other.starts_with('-') {
                unexpected_argument(other, &format!("{} <SUBCOMMAND>", bin));
            }
            unexpected_argument(other, &format!("{} <SUBCOMMAND>", bin));
        }
    }
}
