fn read_stdin() -> String {
    let mut src = String::new();
    let _ = std::io::stdin().read_to_string(&mut src);
    src.lines().collect::<Vec<_>>().join("\n")
}

fn config_error(e: &ConfigErr) -> ! {
    eprintln!("config error: {}", e);
    process::exit(0);
}

fn panic_like(location: &str, message: &str) -> ! {
    let _ = std::io::stdout().flush();
    eprintln!(
        "\nthread 'main' ({}) panicked at {}:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace",
        process::id(),
        location,
        message
    );
    process::exit(101);
}

fn load_config(conf_path: &str) -> ConfFile {
    let path = Path::new(conf_path);
    if let Err(e) = config::check_conf_path(path) {
        config_error(&e);
    }
    match ConfFile::discover(path) {
        Ok(c) => c,
        Err(e) => config_error(&e),
    }
}

fn collect_files(target: &str, ignore: &[String], conf_ignore: &[String], unrestricted: bool) -> Vec<std::path::PathBuf> {
    let target_path = Path::new(target);
    let mut all_ignore: Vec<String> = ignore.to_vec();
    all_ignore.extend(conf_ignore.iter().cloned());
    let ignore_set = match config::build_ignore_set(&all_ignore, target_path, unrestricted) {
        Ok(i) => i,
        Err(e) => config_error(&e),
    };
    match config::walk_nix_files(target_path, &ignore_set) {
        Ok(f) => f,
        Err(e) => config_error(&e),
    }
}

fn print_reports(path: &str, src: &str, reports: &[lints::Report], format: &OutFormat, out: &mut String) {
    match format {
        OutFormat::Errfmt => out.push_str(&analyze::errfmt(path, src, reports)),
        OutFormat::Stderr => match analyze::pretty(path, src, reports) {
            Ok(s) => out.push_str(&s),
            Err(partial) => {
                print!("{}{}", out, partial);
                panic_like(
                    "/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/ariadne-0.1.3/src/source.rs:109:35",
                    "index out of bounds: the len is 0 but the index is 0",
                );
            }
        },
    }
}

fn run_check(args: cli::CheckArgs) -> i32 {
    let conf = load_config(&args.conf_path);
    let lints = config::enabled_lints(&conf.disabled);
    let mut out = String::new();
    let mut any = false;
    if args.stdin {
        let src = read_stdin();
        let reports = analyze::analyze(&src, &lints);
        if !reports.is_empty() {
            any = true;
        }
        print_reports("<stdin>", &src, &reports, &args.format, &mut out);
    } else {
        let files = collect_files(&args.target, &args.ignore, &conf.ignore, args.unrestricted);
        for file in files {
            let src = match std::fs::read_to_string(&file) {
                Ok(s) => s,
                Err(_) => continue,
            };
            let reports = analyze::analyze(&src, &lints);
            if !reports.is_empty() {
                any = true;
            }
            print_reports(&file.to_string_lossy(), &src, &reports, &args.format, &mut out);
