    // triggered on the first occurrence of a repeated key inside a non-rec attrset
    let parent = match node.parent() {
        Some(p) if p.kind() == NODE_ATTR_SET && !has_token(p, TOKEN_REC) => p,
        _ => return vec![],
    };
    let attrpath = match apv_attrpath(node) {
        Some(a) => a,
        None => return vec![],
    };
    let comps: Vec<Node> = attrs(attrpath).collect();
    if comps.len() < 2 {
        return vec![];
    }
    let name = match ident_text(comps[0]) {
        Some(n) => n.to_string(),
        None => return vec![],
    };
    // collect all sibling entries with the same first key
    let mut occurrences: Vec<Node> = Vec::new();
    for apv in attrpath_values(parent) {
        let ap = match apv_attrpath(apv) {
            Some(a) => a,
            None => continue,
        };
        let first = match attrs(ap).next() {
            Some(f) => f,
            None => continue,
        };
        if ident_text(first) == Some(name.as_str()) {
