/// Classic LCS table based diff with a backwards walk (prefers insertions
/// when walking back, i.e. deletions come first in the forward output).
pub fn lcs_diff<T: PartialEq>(old: &[T], new: &[T]) -> Vec<DiffOp> {
    let n = old.len();
    let m = new.len();
    // table[i][j] = lcs length of old[..i] and new[..j]
    let mut table = vec![vec![0u32; m + 1]; n + 1];
    for i in 0..n {
        for j in 0..m {
            table[i + 1][j + 1] = if old[i] == new[j] {
                table[i][j] + 1
            } else {
                table[i][j + 1].max(table[i + 1][j])
            };
        }
    }
    #[derive(Clone, Copy)]
    enum Step {
        Both,
        Left,
        Right,
    }
    let mut steps: Vec<Step> = Vec::new();
    let mut i = n;
    let mut j = m;
    loop {
        if j > 0 && (i == 0 || table[i][j] == table[i][j - 1]) {
            j -= 1;
            steps.push(Step::Right);
        } else if i > 0 && (j == 0 || table[i][j] == table[i - 1][j]) {
            i -= 1;
            steps.push(Step::Left);
        } else if i > 0 && j > 0 {
            i -= 1;
            j -= 1;
            steps.push(Step::Both);
        } else {
            break;
        }
    }
    steps.reverse();
    let mut ops = Vec::new();
    let mut oi = 0;
    let mut ni = 0;
    for step in steps {
        match step {
            Step::Both => {
                ops.push(DiffOp::Equal { old_index: oi, new_index: ni, len: 1 });
                oi += 1;
                ni += 1;
            }
            Step::Left => {
                ops.push(DiffOp::Delete { old_index: oi, old_len: 1, new_index: ni });
                oi += 1;
            }
            Step::Right => {
                ops.push(DiffOp::Insert { old_index: oi, new_index: ni, new_len: 1 });
                ni += 1;
            }
        }
    }
    ops
}

