                if let Some(&(nc, j)) = new_counts.get(&old[i]) {
                    if nc == 1 {
                        pairs.push((i, j));
                    }
                }
            }
        }
    }
    // longest increasing subsequence on j
    let lis = longest_increasing(&pairs);
    if lis.is_empty() {
        let max_d = max_d(old_range.1 - old_range.0, new_range.1 - new_range.0);
        let mut vb = V::new(max_d);
        let mut vf = V::new(max_d);
        conquer(ops, old, old_range, new, new_range, &mut vf, &mut vb);
        return;
    }
    let mut o = old_range.0;
    let mut n = new_range.0;
    for (i, j) in lis {
        patience_rec(ops, old, (o, i), new, (n, j));
        ops.push(DiffOp::Equal { old_index: i, new_index: j, len: 1 });
        o = i + 1;
        n = j + 1;
    }
    patience_rec(ops, old, (o, old_range.1), new, (n, new_range.1));
}

fn longest_increasing(pairs: &[(usize, usize)]) -> Vec<(usize, usize)> {
    if pairs.is_empty() {
        return vec![];
    }
    let n = pairs.len();
    let mut len = vec![1usize; n];
    let mut prev = vec![usize::MAX; n];
    for i in 0..n {
        for k in 0..i {
            if pairs[k].1 < pairs[i].1 && len[k] + 1 > len[i] {
                len[i] = len[k] + 1;
                prev[i] = k;
            }
        }
    }
    let mut best = 0;
    for i in 0..n {
        if len[i] > len[best] {
            best = i;
        }
    }
    let mut out = Vec::new();
    let mut cur = best;
    loop {
        out.push(pairs[cur]);
        if prev[cur] == usize::MAX {
            break;
        }
        cur = prev[cur];
    }
    out.reverse();
    out
}

