def body_from_ops(ops, n=4):
    # ops: list of (tag, text) with tags ' ', '-', '+'. Return unified body lines w/ context n, hunks concatenated.
    # group runs
    runs = []
    for t, x in ops:
        if runs and runs[-1][0] == (t == ' '):
            runs[-1][1].append((t, x))
        else:
            runs.append([t == ' ', [(t, x)]])
    if all(r[0] for r in runs):
        return []
    # trim first/last equal runs
    if runs and runs[0][0]:
        runs[0][1] = runs[0][1][-n:]
    if runs and runs[-1][0]:
        runs[-1][1] = runs[-1][1][:n]
    out = []
    for idx, (eq, items) in enumerate(runs):
        if eq and 0 < idx < len(runs)-1 and len(items) > 2*n:
            items = items[:n] + items[-n:]
        if eq:
            out.extend(' '+x for t, x in items)
        else:
            out.extend(to_unified_core(items))
    return out

def run_all(alg):
    fail = 0
    shown = 0
    for f in sorted(glob.glob('d*.nix')):
        old = open(f).read().split('\n')[:-1]
        new = [('x' if l=='(x)' else 'y' if l=='(y)' else l) for l in old]
