def classic_myers(old, new):
    n, m = len(old), len(new)
    maxd = n + m
    off = maxd + 1
    v = [0]*(2*maxd+3)
    trace = []
    found = False
    for d in range(maxd+1):
        trace.append(v[:])
        for k in range(-d, d+1, 2):
            if k == -d or (k != d and v[off+k-1] < v[off+k+1]):
                x = v[off+k+1]
            else:
                x = v[off+k-1] + 1
            y = x - k
            while x < n and y < m and old[x] == new[y]:
                x += 1; y += 1
            v[off+k] = x
            if x >= n and y >= m:
                found = True
                break
        if found: break
    # backtrack
    ops = []
    x, y = n, m
    for d in range(len(trace)-1, -1, -1):
        vv = trace[d]
        k = x - y
        if k == -d or (k != d and vv[off+k-1] < vv[off+k+1]):
            prev_k = k + 1
        else:
            prev_k = k - 1
        prev_x = vv[off+prev_k]
        prev_y = prev_x - prev_k
        while x > prev_x and y > prev_y:
            ops.append((' ', old[x-1])); x -= 1; y -= 1
        if d > 0:
            if x == prev_x:
                ops.append(('+', new[prev_y])); 
            else:
                ops.append(('-', old[prev_x]))
        x, y = prev_x, prev_y
    ops.reverse()
    return ops
