/// Compaction pass: shifts deletions and insertions up and down the diff so
/// that they connect with each other where possible.
fn cleanup_diff_ops<T: PartialEq>(old: &[T], new: &[T], ops: &mut Vec<DiffOp>) {
    // First attempt to compact all deletions
    let mut pointer = 0;
    while pointer < ops.len() {
        if ops[pointer].is_delete() {
            pointer = shift_diff_ops_up(ops, old, new, pointer);
            pointer = shift_diff_ops_down(ops, old, new, pointer);
        }
        pointer += 1;
    }
    // Then attempt to compact all insertions
    let mut pointer = 0;
    while pointer < ops.len() {
        if ops[pointer].is_insert() {
            pointer = shift_diff_ops_up(ops, old, new, pointer);
            pointer = shift_diff_ops_down(ops, old, new, pointer);
        }
        pointer += 1;
    }
}

fn shift_diff_ops_up<T: PartialEq>(ops: &mut Vec<DiffOp>, old: &[T], new: &[T], mut pointer: usize) -> usize {
    while pointer > 0 {
        let prev_op = ops[pointer - 1];
        let this_op = ops[pointer];
        let suffix_len = if this_op.is_insert() && prev_op.is_equal() {
            common_suffix_len(old, prev_op.old_range(), new, this_op.new_range())
        } else if this_op.is_delete() && prev_op.is_equal() {
            common_suffix_len(old, prev_op.old_range(), old, this_op.old_range())
        } else if (this_op.is_insert() && prev_op.is_delete()) || (this_op.is_delete() && prev_op.is_insert()) {
            ops.swap(pointer - 1, pointer);
            pointer -= 1;
            continue;
        } else if (this_op.is_insert() && prev_op.is_insert()) || (this_op.is_delete() && prev_op.is_delete()) {
            let len = if this_op.is_insert() {
                this_op.new_range().1 - this_op.new_range().0
            } else {
                this_op.old_range().1 - this_op.old_range().0
            };
            ops[pointer - 1].grow_right(len);
            ops.remove(pointer);
            pointer -= 1;
            continue;
        } else {
            break;
        };
        if suffix_len > 0 {
            if pointer + 1 < ops.len() && ops[pointer + 1].is_equal() {
                ops[pointer + 1].grow_left(suffix_len);
            } else {
                ops.insert(
                    pointer + 1,
                    DiffOp::Equal {
                        old_index: this_op.old_range().1 - suffix_len,
                        new_index: this_op.new_range().1 - suffix_len,
                        len: suffix_len,
                    },
                );
            }
            ops[pointer].shift_left(suffix_len);
            ops[pointer - 1].shrink_left(suffix_len);
            if ops[pointer - 1].is_empty() {
                ops.remove(pointer - 1);
                pointer -= 1;
            }
        } else if ops[pointer - 1].is_empty() {
            ops.remove(pointer - 1);
            pointer -= 1;
        } else {
            break;
        }
    }
    pointer
}

fn shift_diff_ops_down<T: PartialEq>(ops: &mut Vec<DiffOp>, old: &[T], new: &[T], mut pointer: usize) -> usize {
    while pointer + 1 < ops.len() {
        let next_op = ops[pointer + 1];
        let this_op = ops[pointer];
        let prefix_len = if this_op.is_insert() && next_op.is_equal() {
            common_prefix_len(old, next_op.old_range(), new, this_op.new_range())
        } else if this_op.is_delete() && next_op.is_equal() {
            common_prefix_len(old, next_op.old_range(), old, this_op.old_range())
        } else if (this_op.is_insert() && next_op.is_delete()) || (this_op.is_delete() && next_op.is_insert()) {
            ops.swap(pointer, pointer + 1);
            pointer += 1;
            continue;
        } else if (this_op.is_insert() && next_op.is_insert()) || (this_op.is_delete() && next_op.is_delete()) {
            let len = if next_op.is_insert() {
                next_op.new_range().1 - next_op.new_range().0
            } else {
                next_op.old_range().1 - next_op.old_range().0
            };
            ops[pointer].grow_right(len);
            ops.remove(pointer + 1);
            continue;
        } else {
            break;
        };
        if prefix_len > 0 {
            if pointer > 0 && ops[pointer - 1].is_equal() {
                ops[pointer - 1].grow_right(prefix_len);
            } else {
                ops.insert(
                    pointer,
                    DiffOp::Equal {
                        old_index: this_op.old_range().0,
                        new_index: this_op.new_range().0,
                        len: prefix_len,
                    },
                );
                pointer += 1;
            }
            ops[pointer].shift_right(prefix_len);
            ops[pointer + 1].shrink_right(prefix_len);
            if ops[pointer + 1].is_empty() {
                ops.remove(pointer + 1);
            }
        } else if ops[pointer + 1].is_empty() {
            ops.remove(pointer + 1);
        } else {
            break;
        }
    }
    pointer
}

